-- BẢN CHIA SẺ: V2 (30 bảng lõi) + UserPreferences cho cá nhân hóa CookHub.
-- Đọc BaoCaoCSDLThucDon.txt trước khi sử dụng.
-- SQL Server 2022. SSMS: Query > SQLCMD Mode. Hoặc sqlcmd -b -f 65001 -i <file>.
-- Không chạy lại để nâng cấp DB đã có. Không có DROP DATABASE, không ghi đè dữ liệu.
-- Đã siết CHECK, kiểm tra DELETE và các trường hợp biên của function; xem báo cáo.
--:ON ERROR EXIT
-- BẢN THAM CHIẾU V2 — 29/09/2026 — SQL Server 2022, compatibility 160.
-- CHỈ TẠO DATABASE MỚI. Không phải migration cho database đang sử dụng.
-- Chạy bằng sqlcmd -b -f 65001 hoặc SSMS bật Query > SQLCMD Mode.
-- Nếu database đã tồn tại: DỪNG. Không xóa, không ghi đè.
USE master;
GO
IF DB_ID(N'QuanLyThucDon') IS NOT NULL
    THROW 51000, N'Database QuanLyThucDon đã tồn tại. Dừng để bảo vệ dữ liệu.', 1;
GO
CREATE DATABASE QuanLyThucDon;
GO
ALTER DATABASE QuanLyThucDon SET COMPATIBILITY_LEVEL = 160;
GO
USE QuanLyThucDon;
GO
SET ANSI_NULLS ON;
SET QUOTED_IDENTIFIER ON;
GO
CREATE TABLE dbo.NguoiDung (
    MaNguoiDung NVARCHAR(20) PRIMARY KEY,
    HoTen NVARCHAR(100) NOT NULL,
    ThuDienTu NVARCHAR(150) NOT NULL UNIQUE,
    MatKhauBam NVARCHAR(255) NOT NULL,
    VaiTro NVARCHAR(30) NOT NULL DEFAULT N'Người dùng',
    TrangThai NVARCHAR(30) NOT NULL DEFAULT N'Đang hoạt động',
    NgayTao DATETIME2(3) NOT NULL DEFAULT SYSDATETIME(),
    CONSTRAINT KiemTraVaiTroNguoiDung
        CHECK (VaiTro IN (N'Người dùng', N'Quản trị viên')),
    CONSTRAINT KiemTraTrangThaiNguoiDung
        CHECK (TrangThai IN (N'Đang hoạt động', N'Tạm khóa'))
);

CREATE TABLE dbo.KhauVi (
    MaKhauVi NVARCHAR(20) PRIMARY KEY,
    TenKhauVi NVARCHAR(100) NOT NULL UNIQUE,
    MoTa NVARCHAR(500)
);

CREATE TABLE dbo.CheDoAn (
    MaCheDoAn NVARCHAR(20) PRIMARY KEY,
    TenCheDoAn NVARCHAR(100) NOT NULL UNIQUE,
    MoTa NVARCHAR(500)
);

CREATE TABLE dbo.SoThichKhauVi (
    MaSoThichKhauVi NVARCHAR(20) PRIMARY KEY,
    MaNguoiDung NVARCHAR(20) NOT NULL,
    MaKhauVi NVARCHAR(20) NOT NULL,
    CONSTRAINT KhongTrungSoThichKhauVi UNIQUE (MaNguoiDung, MaKhauVi),
    CONSTRAINT FkSoThichKhauViNguoiDung
        FOREIGN KEY (MaNguoiDung) REFERENCES NguoiDung(MaNguoiDung)
        ON UPDATE NO ACTION ON DELETE NO ACTION,
    CONSTRAINT FkSoThichKhauViKhauVi
        FOREIGN KEY (MaKhauVi) REFERENCES KhauVi(MaKhauVi)
        ON UPDATE NO ACTION ON DELETE NO ACTION
);

CREATE TABLE dbo.CheDoAnNguoiDung (
    MaCheDoAnNguoiDung NVARCHAR(20) PRIMARY KEY,
    MaNguoiDung NVARCHAR(20) NOT NULL,
    MaCheDoAn NVARCHAR(20) NOT NULL,
    CONSTRAINT KhongTrungCheDoAnNguoiDung UNIQUE (MaNguoiDung, MaCheDoAn),
    CONSTRAINT FkCheDoAnNguoiDungNguoiDung
        FOREIGN KEY (MaNguoiDung) REFERENCES NguoiDung(MaNguoiDung)
        ON UPDATE NO ACTION ON DELETE NO ACTION,
    CONSTRAINT FkCheDoAnNguoiDungCheDoAn
        FOREIGN KEY (MaCheDoAn) REFERENCES CheDoAn(MaCheDoAn)
        ON UPDATE NO ACTION ON DELETE NO ACTION
);

CREATE TABLE dbo.NganSachAnUong (
    MaNganSach NVARCHAR(20) PRIMARY KEY,
    MaNguoiDung NVARCHAR(20) NOT NULL,
    MucNganSach DECIMAL(14,2) NOT NULL,
    LoaiNganSach NVARCHAR(20) NOT NULL,
    NgayBatDau DATE NOT NULL,
    NgayKetThuc DATE NOT NULL,
    CONSTRAINT KiemTraMucNganSach CHECK (MucNganSach > 0),
    CONSTRAINT KiemTraLoaiNganSach CHECK (LoaiNganSach IN (N'Ngày', N'Tuần', N'Tháng')),
    CONSTRAINT KiemTraThoiGianNganSach CHECK (NgayKetThuc >= NgayBatDau),
    CONSTRAINT FkNganSachNguoiDung
        FOREIGN KEY (MaNguoiDung) REFERENCES NguoiDung(MaNguoiDung)
        ON UPDATE NO ACTION ON DELETE NO ACTION
);

CREATE TABLE dbo.MucTieuDinhDuong (
    MaMucTieu NVARCHAR(20) PRIMARY KEY,
    MaNguoiDung NVARCHAR(20) NOT NULL UNIQUE,
    NangLuong DECIMAL(10,2) NOT NULL,
    ChatDam DECIMAL(10,2) NOT NULL,
    ChatBotDuong DECIMAL(10,2) NOT NULL,
    ChatBeo DECIMAL(10,2) NOT NULL,
    ChatXo DECIMAL(10,2) NOT NULL,
    natri DECIMAL(10,2) NOT NULL,
    CONSTRAINT KiemTraMucTieuNangLuong CHECK (NangLuong > 0),
    CONSTRAINT KiemTraMucTieuDinhDuong CHECK (
        ChatDam >= 0 AND ChatBotDuong >= 0 AND ChatBeo >= 0 AND ChatXo >= 0 AND natri >= 0
    ),
    CONSTRAINT FkMucTieuNguoiDung
        FOREIGN KEY (MaNguoiDung) REFERENCES NguoiDung(MaNguoiDung)
        ON UPDATE NO ACTION ON DELETE NO ACTION
);

-- ============================================================
-- TAO BANG: NGUYEN LIEU, DON VI, GIA VA DINH DUONG
-- ============================================================

CREATE TABLE dbo.DonViTinh (
    MaDonVi NVARCHAR(20) PRIMARY KEY,
    TenDonVi NVARCHAR(100) NOT NULL UNIQUE,
    KyHieu NVARCHAR(20) NOT NULL UNIQUE,
    HeSoGramChuan DECIMAL(12,3) NULL,
    CONSTRAINT CkDonViHeSo CHECK (HeSoGramChuan IS NULL OR HeSoGramChuan > 0)
);

CREATE TABLE dbo.NguyenLieu (
    MaNguyenLieu NVARCHAR(20) PRIMARY KEY,
    TenNguyenLieu NVARCHAR(150) NOT NULL UNIQUE,
    MoTa NVARCHAR(500)
);

CREATE TABLE dbo.QuyDoiDonViNguyenLieu (
    MaQuyDoi NVARCHAR(20) PRIMARY KEY,
    MaNguyenLieu NVARCHAR(20) NOT NULL,
    MaDonVi NVARCHAR(20) NOT NULL,
    KhoiLuongQuyDoiGram DECIMAL(12,3) NOT NULL,
    CONSTRAINT KhongTrungQuyDoi UNIQUE (MaNguyenLieu, MaDonVi),
    CONSTRAINT KiemTraKhoiLuongQuyDoi CHECK (KhoiLuongQuyDoiGram > 0),
    CONSTRAINT FkQuyDoiNguyenLieu
        FOREIGN KEY (MaNguyenLieu) REFERENCES NguyenLieu(MaNguyenLieu)
        ON UPDATE NO ACTION ON DELETE NO ACTION,
    CONSTRAINT FkQuyDoiDonVi
        FOREIGN KEY (MaDonVi) REFERENCES DonViTinh(MaDonVi)
        ON UPDATE NO ACTION ON DELETE NO ACTION
);

CREATE TABLE dbo.NguyenLieuThayThe (
    MaThayThe NVARCHAR(20) PRIMARY KEY,
    MaNguyenLieuGoc NVARCHAR(20) NOT NULL,
    MaNguyenLieuThayThe NVARCHAR(20) NOT NULL,
    TyLeQuyDoi DECIMAL(10,3) NOT NULL DEFAULT 1,
    CONSTRAINT KhongTrungNguyenLieuThayThe UNIQUE (MaNguyenLieuGoc, MaNguyenLieuThayThe),
    CONSTRAINT KiemTraNguyenLieuKhacNhau CHECK (MaNguyenLieuGoc <> MaNguyenLieuThayThe),
    CONSTRAINT KiemTraTyLeQuyDoi CHECK (TyLeQuyDoi > 0),
    CONSTRAINT FkThayTheNguyenLieuGoc
        FOREIGN KEY (MaNguyenLieuGoc) REFERENCES NguyenLieu(MaNguyenLieu)
        ON UPDATE NO ACTION ON DELETE NO ACTION,
    CONSTRAINT FkThayTheNguyenLieuMoi
        FOREIGN KEY (MaNguyenLieuThayThe) REFERENCES NguyenLieu(MaNguyenLieu)
        ON UPDATE NO ACTION ON DELETE NO ACTION
);

CREATE TABLE dbo.NguyenLieuHienCo (
    MaChiTiet NVARCHAR(20) PRIMARY KEY,
    MaNguoiDung NVARCHAR(20) NOT NULL,
    MaNguyenLieu NVARCHAR(20) NOT NULL,
    MaDonVi NVARCHAR(20) NOT NULL,
    SoLuong DECIMAL(12,3) NOT NULL,
    NgayCapNhat DATE NOT NULL,
    CONSTRAINT KhongTrungNguyenLieuHienCo UNIQUE (MaNguoiDung, MaNguyenLieu, MaDonVi),
    CONSTRAINT KiemTraSoLuongHienCo CHECK (SoLuong >= 0),
    CONSTRAINT FkNguyenLieuHienCoNguoiDung
        FOREIGN KEY (MaNguoiDung) REFERENCES NguoiDung(MaNguoiDung)
        ON UPDATE NO ACTION ON DELETE NO ACTION,
    CONSTRAINT FkNguyenLieuHienCoNguyenLieu
        FOREIGN KEY (MaNguyenLieu) REFERENCES NguyenLieu(MaNguyenLieu)
        ON UPDATE NO ACTION ON DELETE NO ACTION,
    CONSTRAINT FkNguyenLieuHienCoDonVi
        FOREIGN KEY (MaDonVi) REFERENCES DonViTinh(MaDonVi)
        ON UPDATE NO ACTION ON DELETE NO ACTION
);

CREATE TABLE dbo.GiaNguyenLieu (
    MaGia NVARCHAR(20) PRIMARY KEY,
    MaNguyenLieu NVARCHAR(20) NOT NULL,
	    MaDonVi NVARCHAR(20) NOT NULL,
    GiaThamKhao DECIMAL(14,2) NOT NULL,
    NgayApDung DATE NOT NULL,
    nguon NVARCHAR(200),
    KhuVuc NVARCHAR(150),
    CONSTRAINT KiemTraGiaThamKhao CHECK (GiaThamKhao >= 0),
    CONSTRAINT KhongTrungGiaCungNgay UNIQUE (MaNguyenLieu, MaDonVi, NgayApDung, KhuVuc),
    CONSTRAINT FkGiaNguyenLieu
        FOREIGN KEY (MaNguyenLieu) REFERENCES NguyenLieu(MaNguyenLieu)
        ON UPDATE NO ACTION ON DELETE NO ACTION,
    CONSTRAINT FkGiaDonVi
        FOREIGN KEY (MaDonVi) REFERENCES DonViTinh(MaDonVi)
        ON UPDATE NO ACTION ON DELETE NO ACTION
);

CREATE TABLE dbo.ThongTinDinhDuong (
    MaThongTin NVARCHAR(20) PRIMARY KEY,
    MaNguyenLieu NVARCHAR(20) NOT NULL UNIQUE,
    KhoiLuongChuan DECIMAL(10,2) NOT NULL DEFAULT 100,
    MaDonVi NVARCHAR(20) NOT NULL,
    NangLuong DECIMAL(10,2) NOT NULL,
    ChatDam DECIMAL(10,2) NOT NULL,
    ChatBotDuong DECIMAL(10,2) NOT NULL,
    ChatBeo DECIMAL(10,2) NOT NULL,
    ChatXo DECIMAL(10,2) NOT NULL,
    natri DECIMAL(10,2) NOT NULL,
    CONSTRAINT KiemTraKhoiLuongChuan CHECK (KhoiLuongChuan > 0),
    CONSTRAINT KiemTraDinhDuongNguyenLieu CHECK (
        NangLuong >= 0 AND ChatDam >= 0 AND ChatBotDuong >= 0 AND
        ChatBeo >= 0 AND ChatXo >= 0 AND natri >= 0
    ),
    CONSTRAINT FkDinhDuongNguyenLieu
        FOREIGN KEY (MaNguyenLieu) REFERENCES NguyenLieu(MaNguyenLieu)
        ON UPDATE NO ACTION ON DELETE NO ACTION,
    CONSTRAINT FkDinhDuongDonVi
        FOREIGN KEY (MaDonVi) REFERENCES DonViTinh(MaDonVi)
        ON UPDATE NO ACTION ON DELETE NO ACTION
);

-- ============================================================
-- TAO BANG: MON AN, CONG THUC VA HUONG DAN CHE BIEN
-- ============================================================

CREATE TABLE dbo.DanhMucMonAn (
    MaDanhMuc NVARCHAR(20) PRIMARY KEY,
    TenDanhMuc NVARCHAR(100) NOT NULL UNIQUE,
    MoTa NVARCHAR(500)
);

CREATE TABLE dbo.MonAn (
    MaMonAn NVARCHAR(20) PRIMARY KEY,
    MaDanhMuc NVARCHAR(20) NOT NULL,
    TenMonAn NVARCHAR(150) NOT NULL UNIQUE,
    MoTa NVARCHAR(1000),
    ThoiGianCheBien INT NOT NULL,
    DoKho NVARCHAR(30) NOT NULL,
    DuongDanAnh NVARCHAR(500),
    CONSTRAINT KiemTraThoiGianCheBien CHECK (ThoiGianCheBien > 0),
    CONSTRAINT KiemTraDoKho CHECK (DoKho IN (N'Dễ', N'Trung bình', N'Khó')),
    CONSTRAINT FkMonAnDanhMuc
        FOREIGN KEY (MaDanhMuc) REFERENCES DanhMucMonAn(MaDanhMuc)
        ON UPDATE NO ACTION ON DELETE NO ACTION
);

CREATE TABLE dbo.KhauViMonAn (
    MaKhauViMonAn NVARCHAR(20) PRIMARY KEY,
    MaMonAn NVARCHAR(20) NOT NULL,
    MaKhauVi NVARCHAR(20) NOT NULL,
    CONSTRAINT KhongTrungKhauViMonAn UNIQUE (MaMonAn, MaKhauVi),
    CONSTRAINT FkKhauViMonAnMonAn
        FOREIGN KEY (MaMonAn) REFERENCES MonAn(MaMonAn)
        ON UPDATE NO ACTION ON DELETE NO ACTION,
    CONSTRAINT FkKhauViMonAnKhauVi
        FOREIGN KEY (MaKhauVi) REFERENCES KhauVi(MaKhauVi)
        ON UPDATE NO ACTION ON DELETE NO ACTION
);

CREATE TABLE dbo.CheDoAnMonAn (
    MaCheDoAnMonAn NVARCHAR(20) PRIMARY KEY,
    MaMonAn NVARCHAR(20) NOT NULL,
    MaCheDoAn NVARCHAR(20) NOT NULL,
    CONSTRAINT KhongTrungCheDoAnMonAn UNIQUE (MaMonAn, MaCheDoAn),
    CONSTRAINT FkCheDoAnMonAnMonAn
        FOREIGN KEY (MaMonAn) REFERENCES MonAn(MaMonAn)
        ON UPDATE NO ACTION ON DELETE NO ACTION,
    CONSTRAINT FkCheDoAnMonAnCheDoAn
        FOREIGN KEY (MaCheDoAn) REFERENCES CheDoAn(MaCheDoAn)
        ON UPDATE NO ACTION ON DELETE NO ACTION
);

CREATE TABLE dbo.MonYeuThich (
    MaMonYeuThich NVARCHAR(20) PRIMARY KEY,
    MaNguoiDung NVARCHAR(20) NOT NULL,
    MaMonAn NVARCHAR(20) NOT NULL,
    NgayThem DATE NOT NULL,
    CONSTRAINT KhongTrungMonYeuThich UNIQUE (MaNguoiDung, MaMonAn),
    CONSTRAINT FkMonYeuThichNguoiDung
        FOREIGN KEY (MaNguoiDung) REFERENCES NguoiDung(MaNguoiDung)
        ON UPDATE NO ACTION ON DELETE NO ACTION,
    CONSTRAINT FkMonYeuThichMonAn
        FOREIGN KEY (MaMonAn) REFERENCES MonAn(MaMonAn)
        ON UPDATE NO ACTION ON DELETE NO ACTION
);

CREATE TABLE dbo.CongThuc (
    MaCongThuc NVARCHAR(20) PRIMARY KEY,
    MaMonAn NVARCHAR(20) NOT NULL UNIQUE,
    MoTa NVARCHAR(1000),
    SoKhauPhanChuan INT NOT NULL DEFAULT 1,
    DaCongBo BIT NOT NULL CONSTRAINT DfCongThucCongBo DEFAULT 0,
    CONSTRAINT KiemTraKhauPhanChuan CHECK (SoKhauPhanChuan > 0),
    CONSTRAINT FkCongThucMonAn
        FOREIGN KEY (MaMonAn) REFERENCES MonAn(MaMonAn)
        ON UPDATE NO ACTION ON DELETE NO ACTION
);

CREATE TABLE dbo.ThanhPhanCongThuc (
    MaThanhPhan NVARCHAR(20) PRIMARY KEY,
    MaCongThuc NVARCHAR(20) NOT NULL,
    MaNguyenLieu NVARCHAR(20) NOT NULL,
    MaDonVi NVARCHAR(20) NOT NULL,
    SoLuong DECIMAL(12,3) NOT NULL,
    CONSTRAINT KhongTrungThanhPhan UNIQUE (MaCongThuc, MaNguyenLieu),
    CONSTRAINT KiemTraSoLuongThanhPhan CHECK (SoLuong > 0),
    CONSTRAINT FkThanhPhanCongThuc
        FOREIGN KEY (MaCongThuc) REFERENCES CongThuc(MaCongThuc)
        ON UPDATE NO ACTION ON DELETE NO ACTION,
    CONSTRAINT FkThanhPhanNguyenLieu
        FOREIGN KEY (MaNguyenLieu) REFERENCES NguyenLieu(MaNguyenLieu)
        ON UPDATE NO ACTION ON DELETE NO ACTION,
    CONSTRAINT FkThanhPhanDonVi
        FOREIGN KEY (MaDonVi) REFERENCES DonViTinh(MaDonVi)
        ON UPDATE NO ACTION ON DELETE NO ACTION
);

CREATE TABLE dbo.BuocCheBien (
    MaBuoc NVARCHAR(20) PRIMARY KEY,
    MaCongThuc NVARCHAR(20) NOT NULL,
    ThuTu INT NOT NULL,
    NoiDung NVARCHAR(1500) NOT NULL,
    ThoiGianThucHien INT,
    CONSTRAINT KhongTrungThuTuBuoc UNIQUE (MaCongThuc, ThuTu),
    CONSTRAINT KiemTraThuTuBuoc CHECK (ThuTu > 0),
    CONSTRAINT KiemTraThoiGianBuoc CHECK (ThoiGianThucHien IS NULL OR ThoiGianThucHien >= 0),
    CONSTRAINT FkBuocCheBienCongThuc
        FOREIGN KEY (MaCongThuc) REFERENCES CongThuc(MaCongThuc)
        ON UPDATE NO ACTION ON DELETE NO ACTION
);

CREATE TABLE dbo.DoanPhimHuongDan (
    MaDoanPhim NVARCHAR(20) PRIMARY KEY,
    MaCongThuc NVARCHAR(20) NOT NULL,
    TieuDe NVARCHAR(200) NOT NULL,
    DuongDan NVARCHAR(500) NOT NULL,
    MoTa NVARCHAR(500),
    CONSTRAINT FkDoanPhimCongThuc
        FOREIGN KEY (MaCongThuc) REFERENCES CongThuc(MaCongThuc)
        ON UPDATE NO ACTION ON DELETE NO ACTION
);

-- ============================================================
-- TAO BANG: THUC DON VA DAN GIA
-- ============================================================

CREATE TABLE dbo.ThucDon (
    MaThucDon NVARCHAR(20) PRIMARY KEY,
    MaNguoiDung NVARCHAR(20) NOT NULL,
    TenThucDon NVARCHAR(150) NOT NULL,
    LoaiThucDon NVARCHAR(30) NOT NULL,
    NgayBatDau DATE NOT NULL,
    NgayKetThuc DATE NOT NULL,
    TrangThai NVARCHAR(30) NOT NULL,
    NgayTao DATETIME2(3) NOT NULL DEFAULT SYSDATETIME(),
    CONSTRAINT KiemTraLoaiThucDon CHECK (LoaiThucDon IN (N'Ngày', N'Tuần', N'Tự chọn')),
    CONSTRAINT KiemTraThoiGianThucDon CHECK (NgayKetThuc >= NgayBatDau),
    CONSTRAINT KiemTraTrangThaiThucDon CHECK (TrangThai IN (N'Đang dùng', N'Đã lưu', N'Đã kết thúc')),
    CONSTRAINT FkThucDonNguoiDung
        FOREIGN KEY (MaNguoiDung) REFERENCES NguoiDung(MaNguoiDung)
        ON UPDATE NO ACTION ON DELETE NO ACTION
);

CREATE TABLE dbo.ChiTietThucDon (
    MaChiTiet NVARCHAR(20) PRIMARY KEY,
    MaThucDon NVARCHAR(20) NOT NULL,
    MaMonAn NVARCHAR(20) NOT NULL,
    NgayDung DATE NOT NULL,
    BuaAn NVARCHAR(30) NOT NULL,
    SoKhauPhan INT NOT NULL DEFAULT 1,
    CONSTRAINT KhongTrungMonTrongBua UNIQUE (MaThucDon, NgayDung, BuaAn, MaMonAn),
    CONSTRAINT KiemTraBuaAn CHECK (BuaAn IN (N'Bữa sáng', N'Bữa trưa', N'Bữa tối', N'Bữa phụ')),
    CONSTRAINT KiemTraSoKhauPhan CHECK (SoKhauPhan > 0),
	    CONSTRAINT FkChiTietThucDon
        FOREIGN KEY (MaThucDon) REFERENCES ThucDon(MaThucDon)
        ON UPDATE NO ACTION ON DELETE NO ACTION,
    CONSTRAINT FkChiTietMonAn
        FOREIGN KEY (MaMonAn) REFERENCES MonAn(MaMonAn)
        ON UPDATE NO ACTION ON DELETE NO ACTION
);

CREATE TABLE dbo.DanhGiaMonAn (
    MaDanhGia NVARCHAR(20) PRIMARY KEY,
    MaNguoiDung NVARCHAR(20) NOT NULL,
    MaMonAn NVARCHAR(20) NOT NULL,
    SoSao INT NOT NULL,
    NoiDung NVARCHAR(1000),
    NgayDanhGia DATE NOT NULL,
    MaNguoiKiemDuyet NVARCHAR(20) NULL,
    NgayKiemDuyet DATETIME2(3) NULL,
    GhiChuKiemDuyet NVARCHAR(500) NULL,
    CONSTRAINT KhongTrungDanhGiaMonAn UNIQUE (MaNguoiDung, MaMonAn),
    CONSTRAINT KiemTraSoSao CHECK (SoSao BETWEEN 1 AND 5),
    CONSTRAINT FkDanhGiaMonAnNguoiDung
        FOREIGN KEY (MaNguoiDung) REFERENCES NguoiDung(MaNguoiDung)
        ON UPDATE NO ACTION ON DELETE NO ACTION,
    CONSTRAINT FkDanhGiaMonAnMonAn
        FOREIGN KEY (MaMonAn) REFERENCES MonAn(MaMonAn)
        ON UPDATE NO ACTION ON DELETE NO ACTION
);
GO

-- Món không thích: bổ sung theo đề tài và quan hệ khongThich ở mức phân tích.
CREATE TABLE dbo.MonKhongThich (
 MaNguoiDung NVARCHAR(20) NOT NULL,
 MaMonAn NVARCHAR(20) NOT NULL,
 NgayThem DATETIME2(3) NOT NULL CONSTRAINT DfKhongThichNgay DEFAULT SYSUTCDATETIME(),
 CONSTRAINT PkMonKhongThich PRIMARY KEY (MaNguoiDung,MaMonAn),
 CONSTRAINT FkKhongThichNguoi FOREIGN KEY (MaNguoiDung) REFERENCES dbo.NguoiDung(MaNguoiDung),
 CONSTRAINT FkKhongThichMon FOREIGN KEY (MaMonAn) REFERENCES dbo.MonAn(MaMonAn)
);

-- Mỗi lần đánh giá là một snapshot bất biến, đúng bội số 0..* trong sơ đồ.
-- Cho phép kết quả thiếu dữ liệu, nhưng KHÔNG gán phần thiếu bằng 0.
CREATE TABLE dbo.DanhGiaDinhDuongThucDon (
 MaDanhGia NVARCHAR(20) NOT NULL CONSTRAINT PkDanhGiaThucDon PRIMARY KEY,
 MaThucDon NVARCHAR(20) NOT NULL,
 ThoiDiemDanhGia DATETIME2(3) NOT NULL CONSTRAINT DfDanhGiaThoiDiem DEFAULT SYSUTCDATETIME(),
 KhuVuc NVARCHAR(150) NULL,
 TongNangLuong DECIMAL(18,2) NULL,
 TongChatDam DECIMAL(18,2) NULL,
 TongChatBotDuong DECIMAL(18,2) NULL,
 TongChatBeo DECIMAL(18,2) NULL,
 TongChatXo DECIMAL(18,2) NULL,
 TongNatri DECIMAL(18,2) NULL,
 TongChiPhi DECIMAL(18,2) NULL,
 DuDinhDuong BIT NOT NULL,
 DuGia BIT NOT NULL,
 KetQua NVARCHAR(500) NOT NULL,
 CanhBao NVARCHAR(1000) NULL,
 DuLieuTinhJson NVARCHAR(MAX) NOT NULL,
 DoiChieuJson NVARCHAR(MAX) NOT NULL,
 CONSTRAINT FkDanhGiaDinhDuongThucDon FOREIGN KEY (MaThucDon) REFERENCES dbo.ThucDon(MaThucDon),
 CONSTRAINT CkDanhGiaJson CHECK (ISJSON(DuLieuTinhJson,ARRAY)=1 AND ISJSON(DoiChieuJson,OBJECT)=1
  AND COALESCE(ISJSON(JSON_QUERY(DuLieuTinhJson,'$[0]'),OBJECT),0)=1
  AND COALESCE(ISJSON(JSON_QUERY(DoiChieuJson,'$.TheoNgay'),ARRAY),0)=1
  AND COALESCE(ISJSON(JSON_QUERY(DoiChieuJson,'$.NganSach'),ARRAY),0)=1
  AND COALESCE(ISJSON(JSON_QUERY(DoiChieuJson,'$.PhamVi'),OBJECT),0)=1),
 CONSTRAINT CkDanhGiaKhongRong CHECK(LEN(LTRIM(RTRIM(TRANSLATE(MaDanhGia COLLATE Latin1_General_100_BIN2,NCHAR(9)+NCHAR(10)+NCHAR(11)+NCHAR(12)+NCHAR(13)+NCHAR(160)+NCHAR(8239)+NCHAR(12288),REPLICATE(N' ',8)))))>0 AND LEN(LTRIM(RTRIM(TRANSLATE(KetQua COLLATE Latin1_General_100_BIN2,NCHAR(9)+NCHAR(10)+NCHAR(11)+NCHAR(12)+NCHAR(13)+NCHAR(160)+NCHAR(8239)+NCHAR(12288),REPLICATE(N' ',8)))))>0),
 CONSTRAINT CkDanhGiaDayDu CHECK (
  (DuDinhDuong=1 AND TongNangLuong IS NOT NULL AND TongChatDam IS NOT NULL AND TongChatBotDuong IS NOT NULL AND TongChatBeo IS NOT NULL AND TongChatXo IS NOT NULL AND TongNatri IS NOT NULL)
  OR (DuDinhDuong=0 AND TongNangLuong IS NULL AND TongChatDam IS NULL AND TongChatBotDuong IS NULL AND TongChatBeo IS NULL AND TongChatXo IS NULL AND TongNatri IS NULL)),
 CONSTRAINT CkDanhGiaGia CHECK ((DuGia=1 AND TongChiPhi IS NOT NULL) OR (DuGia=0 AND TongChiPhi IS NULL)),
 CONSTRAINT CkDanhGiaKhongAm CHECK (TongNangLuong>=0 AND TongChatDam>=0 AND TongChatBotDuong>=0 AND TongChatBeo>=0 AND TongChatXo>=0 AND TongNatri>=0 AND TongChiPhi>=0)
);

-- Quy ước V2: 'Ngày'=1 ngày; 'Tuần'=7 ngày liên tiếp; tháng ngân sách
-- là một tháng lịch bắt đầu ngày 1. 'Tự chọn' không bị ép thành tuần.
ALTER TABLE dbo.ThucDon ADD CONSTRAINT CkThucDonDoDai CHECK (
 (LoaiThucDon=N'Ngày' AND NgayBatDau=NgayKetThuc) OR
 (LoaiThucDon=N'Tuần' AND DATEDIFF(DAY,NgayBatDau,NgayKetThuc)=6) OR LoaiThucDon=N'Tự chọn');

ALTER TABLE dbo.NganSachAnUong ADD CONSTRAINT CkNganSachDoDai CHECK (
 (LoaiNganSach=N'Ngày' AND NgayBatDau=NgayKetThuc) OR
 (LoaiNganSach=N'Tuần' AND DATEDIFF(DAY,NgayBatDau,NgayKetThuc)=6) OR
 (LoaiNganSach=N'Tháng' AND DAY(NgayBatDau)=1 AND NgayKetThuc=EOMONTH(NgayBatDau)));

ALTER TABLE dbo.NganSachAnUong ADD CONSTRAINT UqNganSachKy UNIQUE(MaNguoiDung,LoaiNganSach,NgayBatDau,NgayKetThuc);

-- Email: chỉ kiểm tra hình thức cơ bản; xác thực email thuộc tầng ứng dụng.
ALTER TABLE dbo.NguoiDung ADD CONSTRAINT CkEmailCoBan CHECK
 (ThuDienTu LIKE N'%_@_%._%' AND TRANSLATE(ThuDienTu COLLATE Latin1_General_100_BIN2,NCHAR(9)+NCHAR(10)+NCHAR(11)+NCHAR(12)+NCHAR(13)+NCHAR(160)+NCHAR(8239)+NCHAR(12288),REPLICATE(N' ',8)) NOT LIKE N'% %' AND ThuDienTu NOT LIKE N'%@%@%');

-- Theo hợp đồng hiện tại chỉ dùng bcrypt; đây không phải xác minh hash/mật khẩu.
ALTER TABLE dbo.NguoiDung ADD CONSTRAINT CkBcryptDinhDang CHECK
 (DATALENGTH(MatKhauBam)=120 AND SUBSTRING(MatKhauBam,5,2) COLLATE Latin1_General_100_BIN2 LIKE N'[0-9][0-9]' AND LEFT(MatKhauBam,4) COLLATE Latin1_General_100_BIN2 IN (N'$2a$',N'$2b$',N'$2y$')
  AND SUBSTRING(MatKhauBam,7,1)=N'$' AND TRY_CONVERT(INT,SUBSTRING(MatKhauBam,5,2)) IS NOT NULL
  AND TRY_CONVERT(INT,SUBSTRING(MatKhauBam,5,2)) BETWEEN 4 AND 31
  AND SUBSTRING(MatKhauBam,8,53) COLLATE Latin1_General_100_BIN2 NOT LIKE N'%[^a-zA-Z0-9./]%');
GO

