ALTER TABLE dbo.ChiTietThucDon ADD CONSTRAINT CkChiTietThucDonKhongRong CHECK (LEN(LTRIM(RTRIM(TRANSLATE(MaChiTiet COLLATE Latin1_General_100_BIN2,NCHAR(9)+NCHAR(10)+NCHAR(11)+NCHAR(12)+NCHAR(13)+NCHAR(160)+NCHAR(8239)+NCHAR(12288),REPLICATE(N' ',8)))))>0 AND LEN(LTRIM(RTRIM(TRANSLATE(MaThucDon COLLATE Latin1_General_100_BIN2,NCHAR(9)+NCHAR(10)+NCHAR(11)+NCHAR(12)+NCHAR(13)+NCHAR(160)+NCHAR(8239)+NCHAR(12288),REPLICATE(N' ',8)))))>0 AND LEN(LTRIM(RTRIM(TRANSLATE(MaMonAn COLLATE Latin1_General_100_BIN2,NCHAR(9)+NCHAR(10)+NCHAR(11)+NCHAR(12)+NCHAR(13)+NCHAR(160)+NCHAR(8239)+NCHAR(12288),REPLICATE(N' ',8)))))>0 AND LEN(LTRIM(RTRIM(TRANSLATE(BuaAn COLLATE Latin1_General_100_BIN2,NCHAR(9)+NCHAR(10)+NCHAR(11)+NCHAR(12)+NCHAR(13)+NCHAR(160)+NCHAR(8239)+NCHAR(12288),REPLICATE(N' ',8)))))>0);
GO

ALTER TABLE dbo.DanhGiaMonAn ADD CONSTRAINT CkDanhGiaMonAnKhongRong CHECK (LEN(LTRIM(RTRIM(TRANSLATE(MaDanhGia COLLATE Latin1_General_100_BIN2,NCHAR(9)+NCHAR(10)+NCHAR(11)+NCHAR(12)+NCHAR(13)+NCHAR(160)+NCHAR(8239)+NCHAR(12288),REPLICATE(N' ',8)))))>0 AND LEN(LTRIM(RTRIM(TRANSLATE(MaNguoiDung COLLATE Latin1_General_100_BIN2,NCHAR(9)+NCHAR(10)+NCHAR(11)+NCHAR(12)+NCHAR(13)+NCHAR(160)+NCHAR(8239)+NCHAR(12288),REPLICATE(N' ',8)))))>0 AND LEN(LTRIM(RTRIM(TRANSLATE(MaMonAn COLLATE Latin1_General_100_BIN2,NCHAR(9)+NCHAR(10)+NCHAR(11)+NCHAR(12)+NCHAR(13)+NCHAR(160)+NCHAR(8239)+NCHAR(12288),REPLICATE(N' ',8)))))>0);
GO

CREATE INDEX IxGiaTraCuu ON dbo.GiaNguyenLieu(MaNguyenLieu,KhuVuc,NgayApDung DESC) INCLUDE(MaDonVi,GiaThamKhao);
CREATE INDEX IxThucDonNguoiNgay ON dbo.ThucDon(MaNguoiDung,NgayBatDau,NgayKetThuc);
CREATE INDEX IxChiTietMon ON dbo.ChiTietThucDon(MaMonAn,NgayDung) INCLUDE(MaThucDon,SoKhauPhan);
CREATE INDEX IxThanhPhanNguyenLieu ON dbo.ThanhPhanCongThuc(MaNguyenLieu,MaCongThuc);
CREATE INDEX IxMonDanhMuc ON dbo.MonAn(MaDanhMuc);
CREATE INDEX IxDanhGiaMon ON dbo.DanhGiaMonAn(MaMonAn) INCLUDE(SoSao);
CREATE INDEX IxSnapshotThucDon ON dbo.DanhGiaDinhDuongThucDon(MaThucDon,ThoiDiemDanhGia DESC);
GO

-- Đổi nguyên liệu theo từng món trong thực đơn, không sửa công thức chung.
-- SoLuong là lượng cho TOÀN BỘ công thức chuẩn; khi tính sẽ nhân tỷ lệ khẩu phần.
CREATE TABLE dbo.TuyBienNguyenLieuThucDon (
 MaChiTiet NVARCHAR(20) NOT NULL,
  MaThanhPhan NVARCHAR(20) NOT NULL,
 MaNguyenLieu NVARCHAR(20) NOT NULL,
 MaDonVi NVARCHAR(20) NOT NULL,
 SoLuong DECIMAL(12,3) NOT NULL,
 CONSTRAINT PkTuyBien PRIMARY KEY(MaChiTiet,MaThanhPhan),
 CONSTRAINT CkTuyBienSoLuong CHECK(SoLuong>0),
 CONSTRAINT FkTuyBienChiTiet FOREIGN KEY(MaChiTiet) REFERENCES dbo.ChiTietThucDon(MaChiTiet),
 CONSTRAINT FkTuyBienThanhPhan FOREIGN KEY(MaThanhPhan) REFERENCES dbo.ThanhPhanCongThuc(MaThanhPhan),
 CONSTRAINT FkTuyBienNguyenLieu FOREIGN KEY(MaNguyenLieu) REFERENCES dbo.NguyenLieu(MaNguyenLieu),
 CONSTRAINT FkTuyBienDonVi FOREIGN KEY(MaDonVi) REFERENCES dbo.DonViTinh(MaDonVi)
);
GO

-- Phản hồi từng lần nấu khác với đánh giá sao tổng quát một lần/người/món.
CREATE TABLE dbo.PhanHoiCheBien (
 MaPhanHoi NVARCHAR(20) NOT NULL CONSTRAINT PkPhanHoiCheBien PRIMARY KEY,
 MaNguoiDung NVARCHAR(20) NOT NULL,
 MaCongThuc NVARCHAR(20) NOT NULL,
 ThoiDiemNau DATETIME2(0) NOT NULL,
 ThanhCong BIT NOT NULL,
 NoiDung NVARCHAR(1500) NOT NULL,
 CONSTRAINT CkPhanHoiThoiDiem CHECK(ThoiDiemNau<=CONVERT(DATETIME2(0),SYSUTCDATETIME())),
 CONSTRAINT CkPhanHoiKhongRong CHECK(LEN(LTRIM(RTRIM(TRANSLATE(MaPhanHoi COLLATE Latin1_General_100_BIN2,NCHAR(9)+NCHAR(10)+NCHAR(11)+NCHAR(12)+NCHAR(13)+NCHAR(160)+NCHAR(8239)+NCHAR(12288),REPLICATE(N' ',8)))))>0 AND LEN(LTRIM(RTRIM(TRANSLATE(NoiDung COLLATE Latin1_General_100_BIN2,NCHAR(9)+NCHAR(10)+NCHAR(11)+NCHAR(12)+NCHAR(13)+NCHAR(160)+NCHAR(8239)+NCHAR(12288),REPLICATE(N' ',8)))))>0),
 CONSTRAINT FkPhanHoiNguoi FOREIGN KEY(MaNguoiDung) REFERENCES dbo.NguoiDung(MaNguoiDung),
 CONSTRAINT FkPhanHoiCongThuc FOREIGN KEY(MaCongThuc) REFERENCES dbo.CongThuc(MaCongThuc)
);
CREATE INDEX IxPhanHoiCongThuc ON dbo.PhanHoiCheBien(MaCongThuc,ThoiDiemNau DESC);
GO

-- FUNCTIONS: chỉ đọc/tính toán; không ghi bảng, không phát sinh giao dịch.
-- NULL = chưa biết/không tính được, khác hoàn toàn giá trị 0.
CREATE OR ALTER FUNCTION dbo.FnQuyDoiSoLuong
(@MaNguyenLieu NVARCHAR(20),@SoLuong DECIMAL(24,8),@DonViNguon NVARCHAR(20),@DonViDich NVARCHAR(20))
RETURNS DECIMAL(28,8)
AS
BEGIN
 IF @SoLuong IS NULL OR @SoLuong<0 RETURN NULL;
 IF NOT EXISTS(SELECT 1 FROM dbo.NguyenLieu WHERE MaNguyenLieu=@MaNguyenLieu) RETURN NULL;
 IF NOT EXISTS(SELECT 1 FROM dbo.DonViTinh WHERE MaDonVi=@DonViNguon)
 OR NOT EXISTS(SELECT 1 FROM dbo.DonViTinh WHERE MaDonVi=@DonViDich) RETURN NULL;
 IF @DonViNguon=@DonViDich RETURN @SoLuong;
 DECLARE @Nguon DECIMAL(12,3),@Dich DECIMAL(12,3);
 SELECT @Nguon=COALESCE(d.HeSoGramChuan,q.KhoiLuongQuyDoiGram)
 FROM dbo.DonViTinh d LEFT JOIN dbo.QuyDoiDonViNguyenLieu q
 ON q.MaDonVi=d.MaDonVi AND q.MaNguyenLieu=@MaNguyenLieu WHERE d.MaDonVi=@DonViNguon;
 SELECT @Dich=COALESCE(d.HeSoGramChuan,q.KhoiLuongQuyDoiGram)
 FROM dbo.DonViTinh d LEFT JOIN dbo.QuyDoiDonViNguyenLieu q
 ON q.MaDonVi=d.MaDonVi AND q.MaNguyenLieu=@MaNguyenLieu WHERE d.MaDonVi=@DonViDich;
 -- Không biến một lượng dương quá nhỏ thành 0; NULL nếu vượt DECIMAL(28,8).
 DECLARE @KetQua DECIMAL(28,8)=TRY_CONVERT(DECIMAL(28,8),@SoLuong * @Nguon / NULLIF(@Dich,0));
 IF @SoLuong>0 AND @KetQua=0 RETURN NULL;
 RETURN @KetQua;
END;
GO

CREATE OR ALTER FUNCTION dbo.FnNhuCauNguyenLieuMon
(@MaMonAn NVARCHAR(20),@SoKhauPhan INT)
RETURNS TABLE
AS RETURN
 SELECT c.MaCongThuc,tp.MaThanhPhan,tp.MaNguyenLieu,tp.MaDonVi,
 NULLIF(TRY_CONVERT(DECIMAL(24,8),CAST(tp.SoLuong AS DECIMAL(19,6))*@SoKhauPhan / c.SoKhauPhanChuan),0) AS SoLuongCan
 FROM dbo.CongThuc c JOIN dbo.ThanhPhanCongThuc tp ON tp.MaCongThuc=c.MaCongThuc
 WHERE c.MaMonAn=@MaMonAn AND @SoKhauPhan>0;
GO

CREATE OR ALTER FUNCTION dbo.FnKiemTraKhoChoMon
(@MaNguoiDung NVARCHAR(20),@MaMonAn NVARCHAR(20),@SoKhauPhan INT)
RETURNS TABLE
AS RETURN
 SELECT n.*,COALESCE(k.SoLuongHienCo,0) AS SoLuongHienCo,
 COALESCE(k.SoDonViChuaQuyDoi,0) AS SoDonViChuaQuyDoi,
 CAST(CASE WHEN n.SoLuongCan IS NULL THEN N'Chưa xác định'
   WHEN COALESCE(k.SoLuongHienCo,0)>=n.SoLuongCan THEN N'Đủ'
   WHEN k.SoDonViChuaQuyDoi>0 THEN N'Chưa xác định'
   WHEN COALESCE(k.SoLuongHienCo,0)>0 THEN N'Thiếu' ELSE N'Không có' END AS NVARCHAR(30)) AS TrangThai,
 CASE WHEN COALESCE(k.SoLuongHienCo,0)>=n.SoLuongCan THEN CAST(0 AS DECIMAL(28,8))
   WHEN k.SoDonViChuaQuyDoi>0 THEN NULL
   ELSE n.SoLuongCan-COALESCE(k.SoLuongHienCo,0) END AS SoLuongThieu
 FROM dbo.FnNhuCauNguyenLieuMon(@MaMonAn,@SoKhauPhan) n
 OUTER APPLY (
  SELECT SUM(q.SoLuong) SoLuongHienCo,
   SUM(CASE WHEN q.SoLuong IS NULL THEN 1 ELSE 0 END) SoDonViChuaQuyDoi
  FROM dbo.NguyenLieuHienCo h
  CROSS APPLY(SELECT dbo.FnQuyDoiSoLuong(h.MaNguyenLieu,h.SoLuong,h.MaDonVi,n.MaDonVi) SoLuong) q
  WHERE h.MaNguoiDung=@MaNguoiDung AND h.MaNguyenLieu=n.MaNguyenLieu AND h.SoLuong>0
 ) k
 WHERE EXISTS(SELECT 1 FROM dbo.NguoiDung WHERE MaNguoiDung=@MaNguoiDung);
GO

-- Giá chọn trong ĐÚNG khu vực, tại ngày sử dụng, có thể quy đổi.
-- @KhuVuc NULL chỉ chọn giá KhuVuc NULL; không lẫn các địa phương.
-- Giá mới nhất có thể quy đổi; cùng ngày ưu tiên cùng đơn vị, sau đó MaGia.
CREATE OR ALTER FUNCTION dbo.FnTinhNguyenLieu
(@MaNguyenLieu NVARCHAR(20),@SoLuong DECIMAL(24,8),@MaDonVi NVARCHAR(20),@Ngay DATE,@KhuVuc NVARCHAR(150))
RETURNS TABLE
AS RETURN
 SELECT dd.MaThongTin,dd.KhoiLuongChuan,dd.MaDonVi AS DonViDinhDuong,
  gia.MaGia,gia.NgayApDung,gia.MaDonVi AS DonViGia,gia.GiaThamKhao,gia.KhuVuc,
  f.HeSoDinhDuong,gia.LuongTinhGia,
  CASE WHEN v.ThieuPhepTinh=0 THEN raw.NangLuong END NangLuong,
  CASE WHEN v.ThieuPhepTinh=0 THEN raw.ChatDam END ChatDam,
  CASE WHEN v.ThieuPhepTinh=0 THEN raw.ChatBotDuong END ChatBotDuong,
  CASE WHEN v.ThieuPhepTinh=0 THEN raw.ChatBeo END ChatBeo,
  CASE WHEN v.ThieuPhepTinh=0 THEN raw.ChatXo END ChatXo,
  CASE WHEN v.ThieuPhepTinh=0 THEN raw.natri END natri,
  CASE WHEN raw.ChiPhi>0 OR @SoLuong=0 OR gia.GiaThamKhao=0 THEN raw.ChiPhi END ChiPhi,
  CAST(CASE WHEN dd.MaThongTin IS NULL THEN 1 ELSE 0 END AS BIT) ThieuDinhDuong,
  CAST(CASE WHEN dd.MaThongTin IS NOT NULL AND v.ThieuPhepTinh=1 THEN 1 ELSE 0 END AS BIT) ThieuQuyDoiDinhDuong,
  CAST(CASE WHEN gia.MaGia IS NULL OR raw.ChiPhi IS NULL OR (@SoLuong>0 AND gia.GiaThamKhao>0 AND raw.ChiPhi=0) THEN 1 ELSE 0 END AS BIT) ThieuGiaKhaDung
 FROM (VALUES(1)) anchor(n)
 LEFT JOIN dbo.ThongTinDinhDuong dd ON dd.MaNguyenLieu=@MaNguyenLieu
 -- Giới hạn precision hệ số trước khi nhân để SQL không tự giảm kết quả còn 6 số lẻ.
 OUTER APPLY(SELECT TRY_CONVERT(DECIMAL(28,12),dbo.FnQuyDoiSoLuong(@MaNguyenLieu,@SoLuong,@MaDonVi,dd.MaDonVi)/NULLIF(dd.KhoiLuongChuan,0)) HeSo) h
 OUTER APPLY(SELECT CASE WHEN h.HeSo>0 OR @SoLuong=0 THEN h.HeSo END HeSoDinhDuong) f
 OUTER APPLY (
  SELECT TOP(1) g.MaGia,g.MaDonVi,g.GiaThamKhao,g.NgayApDung,g.KhuVuc,q.LuongTinhGia
  FROM dbo.GiaNguyenLieu g
  CROSS APPLY(SELECT dbo.FnQuyDoiSoLuong(@MaNguyenLieu,@SoLuong,@MaDonVi,g.MaDonVi) LuongTinhGia) q
  WHERE g.MaNguyenLieu=@MaNguyenLieu AND g.NgayApDung<=@Ngay
   AND (g.KhuVuc=@KhuVuc OR (g.KhuVuc IS NULL AND @KhuVuc IS NULL)) AND q.LuongTinhGia IS NOT NULL
  ORDER BY g.NgayApDung DESC,CASE WHEN g.MaDonVi=@MaDonVi THEN 0 ELSE 1 END,g.MaGia
 ) gia
 CROSS APPLY(SELECT TRY_CONVERT(DECIMAL(28,8),f.HeSoDinhDuong*dd.NangLuong) NangLuong,
  TRY_CONVERT(DECIMAL(28,8),f.HeSoDinhDuong*dd.ChatDam) ChatDam,
  TRY_CONVERT(DECIMAL(28,8),f.HeSoDinhDuong*dd.ChatBotDuong) ChatBotDuong,
  TRY_CONVERT(DECIMAL(28,8),f.HeSoDinhDuong*dd.ChatBeo) ChatBeo,
  TRY_CONVERT(DECIMAL(28,8),f.HeSoDinhDuong*dd.ChatXo) ChatXo,
  TRY_CONVERT(DECIMAL(28,8),f.HeSoDinhDuong*dd.natri) natri,
  TRY_CONVERT(DECIMAL(28,8),gia.LuongTinhGia*gia.GiaThamKhao) ChiPhi) raw
 CROSS APPLY(SELECT CASE WHEN raw.NangLuong IS NULL OR (@SoLuong>0 AND dd.NangLuong>0 AND raw.NangLuong=0) OR
  raw.ChatDam IS NULL OR (@SoLuong>0 AND dd.ChatDam>0 AND raw.ChatDam=0) OR
  raw.ChatBotDuong IS NULL OR (@SoLuong>0 AND dd.ChatBotDuong>0 AND raw.ChatBotDuong=0) OR
  raw.ChatBeo IS NULL OR (@SoLuong>0 AND dd.ChatBeo>0 AND raw.ChatBeo=0) OR
  raw.ChatXo IS NULL OR (@SoLuong>0 AND dd.ChatXo>0 AND raw.ChatXo=0) OR
  raw.natri IS NULL OR (@SoLuong>0 AND dd.natri>0 AND raw.natri=0)
  THEN 1 ELSE 0 END ThieuPhepTinh) v;
GO

CREATE OR ALTER FUNCTION dbo.FnTinhMonAn
(@MaMonAn NVARCHAR(20),@SoKhauPhan INT,@Ngay DATE,@KhuVuc NVARCHAR(150))
RETURNS TABLE
AS RETURN
 SELECT n.*,t.* FROM dbo.FnNhuCauNguyenLieuMon(@MaMonAn,@SoKhauPhan) n
 CROSS APPLY dbo.FnTinhNguyenLieu(n.MaNguyenLieu,n.SoLuongCan,n.MaDonVi,@Ngay,@KhuVuc) t;
GO

CREATE OR ALTER FUNCTION dbo.FnTinhChiTietThucDon
(@MaThucDon NVARCHAR(20),@KhuVuc NVARCHAR(150))
RETURNS TABLE
AS RETURN
 SELECT ct.MaChiTiet,ct.MaMonAn,ct.NgayDung,ct.BuaAn,ct.SoKhauPhan,
  c.MaCongThuc,c.SoKhauPhanChuan,tp.MaThanhPhan,
  tp.MaNguyenLieu AS MaNguyenLieuGoc,n.MaNguyenLieu,n.MaDonVi,n.SoLuongCan,
  CAST(CASE WHEN tb.MaChiTiet IS NULL THEN 0 ELSE 1 END AS BIT) DaTuyBien,
  t.*
 FROM dbo.ChiTietThucDon ct
 LEFT JOIN dbo.CongThuc c ON c.MaMonAn=ct.MaMonAn
 LEFT JOIN dbo.ThanhPhanCongThuc tp ON tp.MaCongThuc=c.MaCongThuc
 LEFT JOIN dbo.TuyBienNguyenLieuThucDon tb ON tb.MaChiTiet=ct.MaChiTiet AND tb.MaThanhPhan=tp.MaThanhPhan
 CROSS APPLY(SELECT COALESCE(tb.MaNguyenLieu,tp.MaNguyenLieu) MaNguyenLieu,
   COALESCE(tb.MaDonVi,tp.MaDonVi) MaDonVi,
   NULLIF(TRY_CONVERT(DECIMAL(24,8),CAST(COALESCE(tb.SoLuong,tp.SoLuong) AS DECIMAL(19,6))*ct.SoKhauPhan/NULLIF(c.SoKhauPhanChuan,0)),0) SoLuongCan) n
 CROSS APPLY dbo.FnTinhNguyenLieu(n.MaNguyenLieu,n.SoLuongCan,n.MaDonVi,ct.NgayDung,@KhuVuc) t
 WHERE ct.MaThucDon=@MaThucDon;
GO
GO

-- Bổ sung nghiệp vụ: SpKiemTraNguoiDungHoatDong
CREATE OR ALTER PROCEDURE dbo.SpKiemTraNguoiDungHoatDong @MaNguoiDung NVARCHAR(20)
AS
BEGIN
    SET NOCOUNT ON;
    IF @MaNguoiDung IS NULL OR LEN(LTRIM(RTRIM(REPLACE(REPLACE(REPLACE(@MaNguoiDung,NCHAR(9),N' '),NCHAR(10),N' '),NCHAR(13),N' '))))=0 THROW 51031,N'@MaNguoiDung không được để trống.',1;
 IF NOT EXISTS(SELECT 1 FROM dbo.NguoiDung WITH(HOLDLOCK) WHERE MaNguoiDung=@MaNguoiDung AND TrangThai=N'Đang hoạt động')
 THROW 51001,N'Người dùng không tồn tại hoặc đã bị khóa.',1;
END;
GO

-- Bổ sung nghiệp vụ: SpKiemTraChuThucDon
CREATE OR ALTER PROCEDURE dbo.SpKiemTraChuThucDon
 @MaNguoiDung NVARCHAR(20),@MaThucDon NVARCHAR(20),@ChoPhepKetThuc BIT=0
AS
BEGIN
    SET NOCOUNT ON;
    IF @MaNguoiDung IS NULL OR LEN(LTRIM(RTRIM(REPLACE(REPLACE(REPLACE(@MaNguoiDung,NCHAR(9),N' '),NCHAR(10),N' '),NCHAR(13),N' '))))=0 THROW 51031,N'@MaNguoiDung không được để trống.',1;
	    IF @MaThucDon IS NULL OR LEN(LTRIM(RTRIM(REPLACE(REPLACE(REPLACE(@MaThucDon,NCHAR(9),N' '),NCHAR(10),N' '),NCHAR(13),N' '))))=0 THROW 51031,N'@MaThucDon không được để trống.',1;
 EXEC dbo.SpKiemTraNguoiDungHoatDong @MaNguoiDung;
 IF NOT EXISTS(SELECT 1 FROM dbo.ThucDon WITH(UPDLOCK,HOLDLOCK) WHERE MaThucDon=@MaThucDon AND MaNguoiDung=@MaNguoiDung)
 THROW 51002,N'Thực đơn không tồn tại hoặc không thuộc người dùng.',1;
 IF @ChoPhepKetThuc=0 AND EXISTS(SELECT 1 FROM dbo.ThucDon WHERE MaThucDon=@MaThucDon AND TrangThai=N'Đã kết thúc')
 THROW 51003,N'Thực đơn đã kết thúc; không được sửa nội dung.',1;
END;
GO

-- Bổ sung nghiệp vụ: SpKiemTraQuanTri
CREATE OR ALTER PROCEDURE dbo.SpKiemTraQuanTri @MaQuanTri NVARCHAR(20)
AS
BEGIN
    SET NOCOUNT ON;
    IF @MaQuanTri IS NULL OR LEN(LTRIM(RTRIM(REPLACE(REPLACE(REPLACE(@MaQuanTri,NCHAR(9),N' '),NCHAR(10),N' '),NCHAR(13),N' '))))=0 THROW 51031,N'@MaQuanTri không được để trống.',1;
 IF NOT EXISTS(SELECT 1 FROM dbo.NguoiDung WITH(HOLDLOCK) WHERE MaNguoiDung=@MaQuanTri AND VaiTro=N'Quản trị viên' AND TrangThai=N'Đang hoạt động')
 THROW 51020,N'Cần tài khoản quản trị đang hoạt động.',1;
END;
GO

-- Rà soát từ 22 procedure gốc: SpLayNguyenLieuHienCo
CREATE OR ALTER PROCEDURE dbo.SpLayNguyenLieuHienCo @MaNguoiDung NVARCHAR(20)
AS
BEGIN
    SET NOCOUNT ON;
    IF @MaNguoiDung IS NULL OR LEN(LTRIM(RTRIM(REPLACE(REPLACE(REPLACE(@MaNguoiDung,NCHAR(9),N' '),NCHAR(10),N' '),NCHAR(13),N' '))))=0 THROW 51031,N'@MaNguoiDung không được để trống.',1;
    EXEC dbo.SpKiemTraNguoiDungHoatDong @MaNguoiDung;
    SELECT h.MaChiTiet, h.MaNguyenLieu, n.TenNguyenLieu, h.SoLuong,
           h.MaDonVi, d.TenDonVi, d.KyHieu, h.NgayCapNhat
    FROM dbo.NguyenLieuHienCo h
    JOIN dbo.NguyenLieu n ON n.MaNguyenLieu = h.MaNguyenLieu
    JOIN dbo.DonViTinh d ON d.MaDonVi = h.MaDonVi
    WHERE h.MaNguoiDung = @MaNguoiDung
    ORDER BY n.TenNguyenLieu;
END;
GO

-- Rà soát từ 22 procedure gốc: SpThemHoacCapNhatNguyenLieuHienCo
CREATE OR ALTER PROCEDURE dbo.SpThemHoacCapNhatNguyenLieuHienCo
    @MaChiTiet NVARCHAR(20), @MaNguoiDung NVARCHAR(20), @MaNguyenLieu NVARCHAR(20),
    @MaDonVi NVARCHAR(20), @SoLuong DECIMAL(12,3)
AS
BEGIN
    SET NOCOUNT ON;
    SET XACT_ABORT ON;
    DECLARE @TranBanDau INT=@@TRANCOUNT;
    BEGIN TRY
        IF @TranBanDau=0 BEGIN TRANSACTION;
        ELSE SAVE TRANSACTION ProcSave;
    IF @MaChiTiet IS NULL OR LEN(LTRIM(RTRIM(REPLACE(REPLACE(REPLACE(@MaChiTiet,NCHAR(9),N' '),NCHAR(10),N' '),NCHAR(13),N' '))))=0 THROW 51031,N'@MaChiTiet không được để trống.',1;
    IF @MaNguoiDung IS NULL OR LEN(LTRIM(RTRIM(REPLACE(REPLACE(REPLACE(@MaNguoiDung,NCHAR(9),N' '),NCHAR(10),N' '),NCHAR(13),N' '))))=0 THROW 51031,N'@MaNguoiDung không được để trống.',1;
    IF @MaNguyenLieu IS NULL OR LEN(LTRIM(RTRIM(REPLACE(REPLACE(REPLACE(@MaNguyenLieu,NCHAR(9),N' '),NCHAR(10),N' '),NCHAR(13),N' '))))=0 THROW 51031,N'@MaNguyenLieu không được để trống.',1;
    IF @MaDonVi IS NULL OR LEN(LTRIM(RTRIM(REPLACE(REPLACE(REPLACE(@MaDonVi,NCHAR(9),N' '),NCHAR(10),N' '),NCHAR(13),N' '))))=0 THROW 51031,N'@MaDonVi không được để trống.',1;
    IF EXISTS(SELECT 1 FROM dbo.NguyenLieuHienCo WITH(UPDLOCK,HOLDLOCK) WHERE MaChiTiet=@MaChiTiet AND (MaNguoiDung<>@MaNguoiDung OR MaNguyenLieu<>@MaNguyenLieu OR MaDonVi<>@MaDonVi)) THROW 51030,N'Mã bản ghi đã thuộc đối tượng khác.',1;
    EXEC dbo.SpKiemTraNguoiDungHoatDong @MaNguoiDung;
    IF NOT EXISTS (SELECT 1 FROM dbo.NguoiDung WHERE MaNguoiDung = @MaNguoiDung) THROW 50001, N'Người dùng không tồn tại.', 1;
    IF NOT EXISTS (SELECT 1 FROM dbo.NguyenLieu WHERE MaNguyenLieu = @MaNguyenLieu) THROW 50002, N'Nguyên liệu không tồn tại.', 1;
    IF NOT EXISTS (SELECT 1 FROM dbo.DonViTinh WHERE MaDonVi = @MaDonVi) THROW 50003, N'Đơn vị không tồn tại.', 1;
    IF @SoLuong IS NULL OR @SoLuong < 0 THROW 50004, N'Số lượng nguyên liệu không hợp lệ.', 1;

        IF EXISTS (SELECT 1 FROM dbo.NguyenLieuHienCo WITH (UPDLOCK, HOLDLOCK)
                   WHERE MaNguoiDung = @MaNguoiDung AND MaNguyenLieu = @MaNguyenLieu AND MaDonVi = @MaDonVi)
            UPDATE dbo.NguyenLieuHienCo SET SoLuong = @SoLuong, NgayCapNhat = CAST(GETDATE() AS DATE)
            WHERE MaNguoiDung = @MaNguoiDung AND MaNguyenLieu = @MaNguyenLieu AND MaDonVi = @MaDonVi;
        ELSE
            INSERT dbo.NguyenLieuHienCo (MaChiTiet, MaNguoiDung, MaNguyenLieu, MaDonVi, SoLuong, NgayCapNhat)
            VALUES (@MaChiTiet, @MaNguoiDung, @MaNguyenLieu, @MaDonVi, @SoLuong, CAST(GETDATE() AS DATE));

        IF @TranBanDau=0 COMMIT TRANSACTION;
    END TRY
    BEGIN CATCH
        IF @TranBanDau=0 AND XACT_STATE()<>0 ROLLBACK TRANSACTION;
        ELSE IF @TranBanDau>0 AND XACT_STATE()=1 ROLLBACK TRANSACTION ProcSave;
        -- Nếu giao dịch của caller đã doomed (XACT_STATE=-1), caller phải rollback toàn bộ.
        THROW;
    END CATCH;
END;
GO

-- Rà soát từ 22 procedure gốc: SpXoaNguyenLieuHienCo
CREATE OR ALTER PROCEDURE dbo.SpXoaNguyenLieuHienCo @MaNguoiDung NVARCHAR(20), @MaChiTiet NVARCHAR(20)
AS
BEGIN
    SET NOCOUNT ON;
    SET XACT_ABORT ON;
    DECLARE @TranBanDau INT=@@TRANCOUNT;
