    IF @MaChiTiet IS NULL OR LEN(LTRIM(RTRIM(REPLACE(REPLACE(REPLACE(@MaChiTiet,NCHAR(9),N' '),NCHAR(10),N' '),NCHAR(13),N' '))))=0 THROW 51031,N'@MaChiTiet không được để trống.',1;
    EXEC dbo.SpKiemTraNguoiDungHoatDong @MaNguoiDung;
    DELETE dbo.NguyenLieuHienCo WHERE MaNguoiDung = @MaNguoiDung AND MaChiTiet = @MaChiTiet;
    IF @@ROWCOUNT = 0 THROW 50005, N'Không tìm thấy nguyên liệu hiện có của người dùng này.', 1;
        IF @TranBanDau=0 COMMIT TRANSACTION;
    END TRY
    BEGIN CATCH
        IF @TranBanDau=0 AND XACT_STATE()<>0 ROLLBACK TRANSACTION;
        ELSE IF @TranBanDau>0 AND XACT_STATE()=1 ROLLBACK TRANSACTION ProcSave;
        -- Nếu giao dịch của caller đã doomed (XACT_STATE=-1), caller phải rollback toàn bộ.
        THROW;
    END CATCH;
END;
GO

-- Rà soát từ 22 procedure gốc: SpTimKiemMonAn
CREATE OR ALTER PROCEDURE dbo.SpTimKiemMonAn
    @TuKhoa NVARCHAR(150) = NULL, @MaDanhMuc NVARCHAR(20) = NULL, @DoKho NVARCHAR(30) = NULL
AS
BEGIN
    SET NOCOUNT ON;

    SELECT m.MaMonAn, m.TenMonAn, dm.TenDanhMuc, m.ThoiGianCheBien, m.DoKho, m.DuongDanAnh,
           CAST(AVG(CAST(g.SoSao AS DECIMAL(10,2))) AS DECIMAL(4,2)) AS DiemDanhGiaTrungBinh,
           COUNT(g.MaDanhGia) AS SoLuotDanhGia
    FROM dbo.MonAn m JOIN dbo.DanhMucMonAn dm ON dm.MaDanhMuc = m.MaDanhMuc
    LEFT JOIN dbo.DanhGiaMonAn g ON g.MaMonAn = m.MaMonAn
    WHERE (@TuKhoa IS NULL OR m.TenMonAn LIKE N'%' + @TuKhoa + N'%' OR m.MoTa LIKE N'%' + @TuKhoa + N'%'
           OR dm.TenDanhMuc LIKE N'%' + @TuKhoa + N'%')
      AND (@MaDanhMuc IS NULL OR m.MaDanhMuc = @MaDanhMuc)
      AND (@DoKho IS NULL OR m.DoKho = @DoKho)
    GROUP BY m.MaMonAn, m.TenMonAn, dm.TenDanhMuc, m.ThoiGianCheBien, m.DoKho, m.DuongDanAnh
    ORDER BY m.TenMonAn;
END;
GO

-- Rà soát từ 22 procedure gốc: SpLayChiTietMonAn
CREATE OR ALTER PROCEDURE dbo.SpLayChiTietMonAn @MaMonAn NVARCHAR(20)
AS
BEGIN
    SET NOCOUNT ON;
    IF @MaMonAn IS NULL OR LEN(LTRIM(RTRIM(REPLACE(REPLACE(REPLACE(@MaMonAn,NCHAR(9),N' '),NCHAR(10),N' '),NCHAR(13),N' '))))=0 THROW 51031,N'@MaMonAn không được để trống.',1;
    IF NOT EXISTS (SELECT 1 FROM dbo.MonAn WHERE MaMonAn = @MaMonAn) THROW 50006, N'Món ăn không tồn tại.', 1;
    SELECT m.*, dm.TenDanhMuc, c.MaCongThuc, c.MoTa AS MoTaCongThuc, c.SoKhauPhanChuan
    FROM dbo.MonAn m JOIN dbo.DanhMucMonAn dm ON dm.MaDanhMuc = m.MaDanhMuc
    LEFT JOIN dbo.CongThuc c ON c.MaMonAn = m.MaMonAn WHERE m.MaMonAn = @MaMonAn;
    SELECT tp.MaThanhPhan, tp.MaNguyenLieu, n.TenNguyenLieu, tp.SoLuong, tp.MaDonVi, d.TenDonVi, d.KyHieu
    FROM dbo.CongThuc c JOIN dbo.ThanhPhanCongThuc tp ON tp.MaCongThuc = c.MaCongThuc
    JOIN dbo.NguyenLieu n ON n.MaNguyenLieu = tp.MaNguyenLieu JOIN dbo.DonViTinh d ON d.MaDonVi = tp.MaDonVi
    WHERE c.MaMonAn = @MaMonAn ORDER BY n.TenNguyenLieu;
    SELECT b.MaBuoc, b.ThuTu, b.NoiDung, b.ThoiGianThucHien FROM dbo.CongThuc c
    JOIN dbo.BuocCheBien b ON b.MaCongThuc = c.MaCongThuc WHERE c.MaMonAn = @MaMonAn ORDER BY b.ThuTu;
    SELECT p.MaDoanPhim, p.TieuDe, p.DuongDan, p.MoTa FROM dbo.CongThuc c
    JOIN dbo.DoanPhimHuongDan p ON p.MaCongThuc = c.MaCongThuc WHERE c.MaMonAn = @MaMonAn;
    SELECT kv.MaKhauVi, kv.TenKhauVi FROM dbo.KhauViMonAn x JOIN dbo.KhauVi kv ON kv.MaKhauVi = x.MaKhauVi
    WHERE x.MaMonAn = @MaMonAn;
    SELECT cd.MaCheDoAn, cd.TenCheDoAn FROM dbo.CheDoAnMonAn x JOIN dbo.CheDoAn cd ON cd.MaCheDoAn = x.MaCheDoAn
    WHERE x.MaMonAn = @MaMonAn;
    SELECT CAST(AVG(CAST(SoSao AS DECIMAL(10,2))) AS DECIMAL(4,2)) AS DiemTrungBinh,
           COUNT(*) AS SoLuotDanhGia FROM dbo.DanhGiaMonAn WHERE MaMonAn = @MaMonAn;
END;
GO

-- Rà soát từ 22 procedure gốc: SpKiemTraNguyenLieuChoMonAn
CREATE OR ALTER PROCEDURE dbo.SpKiemTraNguyenLieuChoMonAn
 @MaNguoiDung NVARCHAR(20),@MaMonAn NVARCHAR(20),@SoKhauPhan INT=1
AS
BEGIN
    SET NOCOUNT ON;
    IF @MaNguoiDung IS NULL OR LEN(LTRIM(RTRIM(REPLACE(REPLACE(REPLACE(@MaNguoiDung,NCHAR(9),N' '),NCHAR(10),N' '),NCHAR(13),N' '))))=0 THROW 51031,N'@MaNguoiDung không được để trống.',1;
    IF @MaMonAn IS NULL OR LEN(LTRIM(RTRIM(REPLACE(REPLACE(REPLACE(@MaMonAn,NCHAR(9),N' '),NCHAR(10),N' '),NCHAR(13),N' '))))=0 THROW 51031,N'@MaMonAn không được để trống.',1;
 EXEC dbo.SpKiemTraNguoiDungHoatDong @MaNguoiDung;
 IF @SoKhauPhan IS NULL OR @SoKhauPhan<=0 THROW 51004,N'Khẩu phần phải lớn hơn 0.',1;
 IF NOT EXISTS(SELECT 1 FROM dbo.CongThuc WHERE MaMonAn=@MaMonAn AND DaCongBo=1)
 THROW 51005,N'Món chưa có công thức được công bố.',1;
 SELECT k.*,n.TenNguyenLieu,d.KyHieu,
  (SELECT tt.MaNguyenLieuThayThe,nt.TenNguyenLieu,tt.TyLeQuyDoi
   FROM dbo.NguyenLieuThayThe tt JOIN dbo.NguyenLieu nt ON nt.MaNguyenLieu=tt.MaNguyenLieuThayThe
   WHERE tt.MaNguyenLieuGoc=k.MaNguyenLieu FOR JSON PATH) NguyenLieuThayTheJson
 FROM dbo.FnKiemTraKhoChoMon(@MaNguoiDung,@MaMonAn,@SoKhauPhan) k
 JOIN dbo.NguyenLieu n ON n.MaNguyenLieu=k.MaNguyenLieu
 JOIN dbo.DonViTinh d ON d.MaDonVi=k.MaDonVi ORDER BY n.TenNguyenLieu;
END;
GO

-- Rà soát từ 22 procedure gốc: SpThemMonYeuThich
CREATE OR ALTER PROCEDURE dbo.SpThemMonYeuThich @MaMonYeuThich NVARCHAR(20), @MaNguoiDung NVARCHAR(20), @MaMonAn NVARCHAR(20)
AS
BEGIN
    SET NOCOUNT ON;
    SET XACT_ABORT ON;
    DECLARE @TranBanDau INT=@@TRANCOUNT;
    BEGIN TRY
        IF @TranBanDau=0 BEGIN TRANSACTION;
        ELSE SAVE TRANSACTION ProcSave;
    IF @MaMonYeuThich IS NULL OR LEN(LTRIM(RTRIM(REPLACE(REPLACE(REPLACE(@MaMonYeuThich,NCHAR(9),N' '),NCHAR(10),N' '),NCHAR(13),N' '))))=0 THROW 51031,N'@MaMonYeuThich không được để trống.',1;
    IF @MaNguoiDung IS NULL OR LEN(LTRIM(RTRIM(REPLACE(REPLACE(REPLACE(@MaNguoiDung,NCHAR(9),N' '),NCHAR(10),N' '),NCHAR(13),N' '))))=0 THROW 51031,N'@MaNguoiDung không được để trống.',1;
    IF @MaMonAn IS NULL OR LEN(LTRIM(RTRIM(REPLACE(REPLACE(REPLACE(@MaMonAn,NCHAR(9),N' '),NCHAR(10),N' '),NCHAR(13),N' '))))=0 THROW 51031,N'@MaMonAn không được để trống.',1;
    IF EXISTS(SELECT 1 FROM dbo.MonYeuThich WITH(UPDLOCK,HOLDLOCK) WHERE MaMonYeuThich=@MaMonYeuThich AND (MaNguoiDung<>@MaNguoiDung OR MaMonAn<>@MaMonAn)) THROW 51030,N'Mã bản ghi đã thuộc đối tượng khác.',1;
    EXEC dbo.SpKiemTraNguoiDungHoatDong @MaNguoiDung;
    IF NOT EXISTS (SELECT 1 FROM dbo.NguoiDung WHERE MaNguoiDung = @MaNguoiDung) THROW 50001, N'Người dùng không tồn tại.', 1;
    IF NOT EXISTS (SELECT 1 FROM dbo.MonAn WHERE MaMonAn = @MaMonAn) THROW 50006, N'Món ăn không tồn tại.', 1;

        DELETE dbo.MonKhongThich WHERE MaNguoiDung=@MaNguoiDung AND MaMonAn=@MaMonAn;
        IF EXISTS (SELECT 1 FROM dbo.MonYeuThich WITH (UPDLOCK, HOLDLOCK) WHERE MaNguoiDung = @MaNguoiDung AND MaMonAn = @MaMonAn)
            SELECT N'DATONTAI' AS TrangThai;
        ELSE
        BEGIN
            INSERT dbo.MonYeuThich (MaMonYeuThich, MaNguoiDung, MaMonAn, NgayThem)
            VALUES (@MaMonYeuThich, @MaNguoiDung, @MaMonAn, CAST(GETDATE() AS DATE));
            SELECT N'DATHEM' AS TrangThai;
        END;

        IF @TranBanDau=0 COMMIT TRANSACTION;
    END TRY
    BEGIN CATCH
        IF @TranBanDau=0 AND XACT_STATE()<>0 ROLLBACK TRANSACTION;
        ELSE IF @TranBanDau>0 AND XACT_STATE()=1 ROLLBACK TRANSACTION ProcSave;
        -- Nếu giao dịch của caller đã doomed (XACT_STATE=-1), caller phải rollback toàn bộ.
        THROW;
    END CATCH;
END;
GO

