VALUES

/* ============================================================
   CT001 - PHỞ BÒ VIÊN
   9 bước - Khó
   ============================================================ */
(N'BCB0001',N'CT001',1,
 N'Rửa gừng và hành tây. Nướng hoặc áp chảo gừng và hành tây đến khi bề mặt hơi cháy xém để tạo mùi thơm cho nước dùng.',
 10),

(N'BCB0002',N'CT001',2,
 N'Cho gia vị phở vào chảo khô, rang trên lửa nhỏ đến khi dậy mùi. Cho gia vị vào túi lọc để dễ lấy ra sau khi nấu.',
 5),

(N'BCB0003',N'CT001',3,
 N'Cho nước vào nồi cùng gừng, hành tây và túi gia vị phở. Đun sôi rồi hạ lửa, nấu liu riu để tạo nước dùng thơm.',
 45),

(N'BCB0004',N'CT001',4,
 N'Nêm nước dùng bằng nước mắm, muối và đường. Tiếp tục nấu nhỏ lửa để các hương vị hòa quyện.',
 20),

(N'BCB0005',N'CT001',5,
 N'Thái thịt bò thành lát thật mỏng theo chiều ngang thớ. Giữ thịt mát cho đến khi chuẩn bị ăn.',
 10),

(N'BCB0006',N'CT001',6,
 N'Cho bò viên vào nước dùng đang sôi nhẹ, nấu đến khi bò viên nóng hoàn toàn.',
 8),

(N'BCB0007',N'CT001',7,
 N'Chần bánh phở trong nước nóng đến khi mềm vừa phải rồi để ráo. Không chần quá lâu để tránh bánh phở bị nát.',
 3),

(N'BCB0008',N'CT001',8,
 N'Chia bánh phở vào tô, xếp thịt bò thái mỏng và bò viên lên trên. Thêm hành lá, rau mùi và hành tây thái mỏng.',
 5),

(N'BCB0009',N'CT001',9,
 N'Đun nước dùng sôi mạnh trở lại rồi chan trực tiếp lên thịt bò để làm chín thịt. Dùng nóng cùng húng quế.',
 4),

/* ============================================================
   CT002 - CƠM GÀ ÁP CHẢO
   6 bước - Trung bình
   ============================================================ */
(N'BCB0010',N'CT002',1,
 N'Vo gạo nhẹ với nước sạch rồi cho vào nồi với lượng nước phù hợp và nấu cơm.',
 5),

(N'BCB0011',N'CT002',2,
 N'Làm sạch ức gà, thấm khô rồi ướp với tỏi băm, nước tương, tiêu và một ít muối.',
 8),

(N'BCB0012',N'CT002',3,
 N'Sơ chế cà rốt và bông cải xanh thành miếng vừa ăn.',
 5),

(N'BCB0013',N'CT002',4,
 N'Làm nóng chảo với dầu. Áp chảo ức gà ở lửa vừa đến khi hai mặt vàng và phần giữa chín hoàn toàn.',
 14),

(N'BCB0014',N'CT002',5,
 N'Cho cà rốt và bông cải vào chảo, xào nhanh hoặc thêm một ít nước rồi đậy nắp cho rau vừa chín tới.',
 6),

(N'BCB0015',N'CT002',6,
 N'Để thịt gà nghỉ vài phút rồi thái lát. Cho cơm ra đĩa, xếp gà và rau củ bên cạnh.',
 4),

/* ============================================================
   CT003 - BÁNH XÈO MIỀN TÂY
   9 bước - Trung bình
   ============================================================ */
(N'BCB0016',N'CT003',1,
 N'Trộn bột gạo, bột nghệ, nước cốt dừa và nước thành hỗn hợp bột tương đối loãng, khuấy đến khi không còn vón cục.',
 8),

(N'BCB0017',N'CT003',2,
 N'Thêm hành lá thái nhỏ vào bột rồi để bột nghỉ trong thời gian chuẩn bị nhân.',
 5),

(N'BCB0018',N'CT003',3,
 N'Thái mỏng thịt heo. Làm sạch tôm, bỏ phần không ăn được và để ráo.',
 8),

(N'BCB0019',N'CT003',4,
 N'Làm nóng chảo, cho một ít dầu rồi xào nhanh thịt heo và tôm đến khi gần chín.',
 7),

(N'BCB0020',N'CT003',5,
 N'Làm nóng chảo sạch với một lớp dầu mỏng. Khuấy bột rồi đổ một lượng vừa đủ vào chảo, nhanh tay xoay chảo để bột tạo lớp mỏng.',
 5),

(N'BCB0021',N'CT003',6,
 N'Cho tôm, thịt và giá đỗ lên một nửa mặt bánh. Đậy nắp trong thời gian ngắn để nhân nóng và giá vừa chín.',
 5),

(N'BCB0022',N'CT003',7,
 N'Mở nắp và tiếp tục chiên đến khi mép bánh giòn, dễ tách khỏi chảo. Gập đôi bánh rồi lấy ra. Lặp lại với lượng bột còn lại.',
 12),

(N'BCB0023',N'CT003',8,
 N'Pha nước chấm từ nước mắm, đường, nước cốt chanh, tỏi và lượng nước phù hợp; khuấy cho đường tan.',
 6),

(N'BCB0024',N'CT003',9,
 N'Dọn bánh xèo khi còn nóng cùng xà lách, húng quế và nước chấm.',
 4),

/* ============================================================
   CT004 - CÁ HỒI ÁP CHẢO
   5 bước - Dễ
   ============================================================ */
(N'BCB0025',N'CT004',1,
 N'Thấm thật khô bề mặt cá hồi rồi nêm muối và tiêu đều hai mặt.',
 4),

(N'BCB0026',N'CT004',2,
 N'Rửa xà lách và dưa leo, để ráo rồi cắt thành miếng vừa ăn.',
 5),

(N'BCB0027',N'CT004',3,
 N'Làm nóng chảo với dầu. Đặt cá hồi vào chảo và áp chảo mặt đầu tiên đến khi vàng.',
 6),

(N'BCB0028',N'CT004',4,
 N'Lật cá, thêm tỏi và tiếp tục áp chảo đến khi cá vừa chín nhưng vẫn còn ẩm bên trong.',
