(N'BCB0031',N'CT005',2,
 N'Cắt cà chua thành múi, dứa thành miếng nhỏ; rửa sạch giá đỗ và rau cần.',
 7),

(N'BCB0032',N'CT005',3,
 N'Cho me vào một ít nước nóng, dằm lấy nước chua rồi lọc bỏ hạt và xác me.',
