(N'BCB0033',N'CT005',4,
 N'Đun nước đến sôi, cho cá vào nấu ở lửa vừa. Hớt bọt nhẹ để nước canh trong hơn.',
 10),

(N'BCB0034',N'CT005',5,
 N'Cho cà chua, dứa và nước me vào nồi. Nêm nước mắm, đường và muối để tạo vị chua, ngọt và mặn cân bằng.',
 7),

(N'BCB0035',N'CT005',6,
 N'Khi cá đã chín, cho giá đỗ và rau cần vào. Nấu thêm thời gian ngắn để rau vẫn giữ độ giòn.',
 3),

(N'BCB0036',N'CT005',7,
 N'Nếm lại nước canh, điều chỉnh gia vị nếu cần rồi tắt bếp và dùng nóng.',
