(N'BCB0055',N'CT009',2,
 N'Cho bơ vào nồi, đun chảy rồi xào hành tây đến khi mềm và thơm.',
 5),

(N'BCB0056',N'CT009',3,
 N'Cho bí đỏ vào đảo cùng hành trong vài phút.',
