INSERT INTO dbo.KhauViMonAn
(
    MaKhauViMonAn,
    MaMonAn,
    MaKhauVi
)
SELECT
    N'KVMA' + RIGHT(
        N'000' + CAST(
            ROW_NUMBER() OVER (ORDER BY MaMonAn, MaKhauVi)
            AS NVARCHAR(10)
        ),
        3
    ) AS MaKhauViMonAn,
    MaMonAn,
    MaKhauVi
FROM
(
    VALUES
    /* MA001 - Phở bò viên */
