/* ============================================================
   23. THỰC ĐƠN
   LƯU Ý:
   Các thực đơn lịch sử được tạo tạm ở trạng thái 'Đã lưu'
   để có thể thêm ChiTietThucDon.
   Sau khi thêm xong chi tiết mới chuyển sang 'Đã kết thúc'.
   ============================================================ */
   UPDATE dbo.ThucDon
SET TrangThai = N'Đã lưu'
WHERE MaThucDon IN
(
    N'TD001',
    N'TD002',
    N'TD004',
    N'TD005',
