 /* ============================================================
   27. TÙY BIẾN NGUYÊN LIỆU THEO THỰC ĐƠN
   ============================================================ */

/* ------------------------------------------------------------
   ND002 - Salad ức gà:
   giảm lượng dầu ăn xuống còn 5 ml cho toàn công thức chuẩn.
   ------------------------------------------------------------ */
INSERT INTO dbo.TuyBienNguyenLieuThucDon
(
    MaChiTiet,
    MaThanhPhan,
    MaNguyenLieu,
    MaDonVi,
    SoLuong
)
SELECT
    N'CTTD011',
    tp.MaThanhPhan,
    tp.MaNguyenLieu,
    N'DVT003',
    CAST(5 AS DECIMAL(12,3))
FROM dbo.ChiTietThucDon ct
JOIN dbo.CongThuc c
    ON c.MaMonAn = ct.MaMonAn
JOIN dbo.ThanhPhanCongThuc tp
    ON tp.MaCongThuc = c.MaCongThuc
JOIN dbo.NguyenLieu nl
    ON nl.MaNguyenLieu = tp.MaNguyenLieu
WHERE ct.MaChiTiet = N'CTTD011'
  AND ct.MaMonAn = N'MA007'
  AND nl.TenNguyenLieu = N'Dầu ăn';


/* ------------------------------------------------------------
   ND002 - Bò xào rau cải:
   tăng rau cải lên 250 g.
   ------------------------------------------------------------ */
INSERT INTO dbo.TuyBienNguyenLieuThucDon
(
    MaChiTiet,
    MaThanhPhan,
    MaNguyenLieu,
    MaDonVi,
    SoLuong
)
SELECT
    N'CTTD020',
    tp.MaThanhPhan,
    tp.MaNguyenLieu,
    N'DVT001',
    CAST(250 AS DECIMAL(12,3))
FROM dbo.ChiTietThucDon ct
JOIN dbo.CongThuc c
    ON c.MaMonAn = ct.MaMonAn
JOIN dbo.ThanhPhanCongThuc tp
    ON tp.MaCongThuc = c.MaCongThuc
JOIN dbo.NguyenLieu nl
    ON nl.MaNguyenLieu = tp.MaNguyenLieu
WHERE ct.MaChiTiet = N'CTTD020'
  AND ct.MaMonAn = N'MA025'
  AND nl.TenNguyenLieu IN (N'Cải xanh', N'Rau cải');


/* ------------------------------------------------------------
   ND002 - Cá basa hấp gừng:
   tăng gừng lên 20 g.
   ------------------------------------------------------------ */
INSERT INTO dbo.TuyBienNguyenLieuThucDon
(
    MaChiTiet,
    MaThanhPhan,
    MaNguyenLieu,
    MaDonVi,
    SoLuong
)
SELECT
    N'CTTD027',
    tp.MaThanhPhan,
    tp.MaNguyenLieu,
    N'DVT001',
    CAST(20 AS DECIMAL(12,3))
FROM dbo.ChiTietThucDon ct
JOIN dbo.CongThuc c
    ON c.MaMonAn = ct.MaMonAn
JOIN dbo.ThanhPhanCongThuc tp
    ON tp.MaCongThuc = c.MaCongThuc
JOIN dbo.NguyenLieu nl
    ON nl.MaNguyenLieu = tp.MaNguyenLieu
WHERE ct.MaChiTiet = N'CTTD027'
  AND ct.MaMonAn = N'MA030'
  AND nl.TenNguyenLieu = N'Gừng';


/* ------------------------------------------------------------
   ND003 - Đậu hũ sốt cà chua:
   tăng cà chua lên 300 g.
   ------------------------------------------------------------ */
INSERT INTO dbo.TuyBienNguyenLieuThucDon
(
    MaChiTiet,
    MaThanhPhan,
    MaNguyenLieu,
