UPDATE dbo.CongThuc SET DaCongBo=1;

-- Không chép 3 tổng đánh giá nhập tay từ file gốc: chúng không có bằng chứng tính.
-- Giữ dữ liệu thiếu giá/dinh dưỡng làm ví dụ kiểm tra trạng thái chưa đủ dữ liệu.

GO

-- Trigger xử lý theo TẬP inserted/deleted, không giả định một dòng.
-- Các kiểm tra liên bảng giữ khóa tới cuối giao dịch. Có thể phát sinh deadlock;
-- backend phải retry toàn giao dịch lỗi 1205 với số lần hữu hạn.
CREATE OR ALTER TRIGGER dbo.TrgChiTietThucDonKiemTraNgayDung
ON dbo.ChiTietThucDon AFTER INSERT,UPDATE,DELETE
AS
BEGIN
 IF ROWCOUNT_BIG()=0 RETURN;
 SET NOCOUNT ON;

 IF UPDATE(MaChiTiet) AND EXISTS(SELECT 1 FROM deleted)
  THROW 51119,N'Mã chi tiết là bất biến.',1;

 DECLARE @LockCount BIGINT;

 SELECT @LockCount=COUNT_BIG(*)
 FROM dbo.ThucDon t WITH(UPDLOCK,HOLDLOCK)
 WHERE t.MaThucDon IN(
    SELECT MaThucDon FROM inserted
    UNION
    SELECT MaThucDon FROM deleted
 );

 IF EXISTS(
    SELECT 1
    FROM inserted i
    JOIN deleted d ON d.MaChiTiet=i.MaChiTiet
    WHERE i.MaThucDon<>d.MaThucDon
 )
  THROW 51101,N'Không được chuyển chi tiết sang thực đơn khác.',1;

 IF EXISTS(
    SELECT 1
    FROM dbo.ThucDon t
    JOIN(
        SELECT MaThucDon FROM inserted
        UNION
        SELECT MaThucDon FROM deleted
    ) x ON x.MaThucDon=t.MaThucDon
    WHERE t.TrangThai=N'Đã kết thúc'
 )
  THROW 51102,N'Không được sửa/xóa món trong thực đơn đã kết thúc.',1;

 IF EXISTS(
    SELECT 1
    FROM inserted i
    JOIN dbo.ThucDon t ON t.MaThucDon=i.MaThucDon
    WHERE i.NgayDung NOT BETWEEN t.NgayBatDau AND t.NgayKetThuc
 )
  THROW 50029,N'Ngày dùng nằm ngoài khoảng thực đơn.',1;

 IF EXISTS(
    SELECT 1
    FROM inserted i
    WHERE NOT EXISTS(
        SELECT 1
        FROM dbo.CongThuc c WITH(HOLDLOCK)
        WHERE c.MaMonAn=i.MaMonAn
          AND c.DaCongBo=1
    )
 )
  THROW 51103,N'Chỉ thêm món có công thức đã công bố.',1;

 IF EXISTS(
    SELECT 1
    FROM inserted i
    JOIN dbo.TuyBienNguyenLieuThucDon tb
      ON tb.MaChiTiet=i.MaChiTiet
    JOIN dbo.ThanhPhanCongThuc tp
      ON tp.MaThanhPhan=tb.MaThanhPhan
    JOIN dbo.CongThuc c
      ON c.MaCongThuc=tp.MaCongThuc
    WHERE c.MaMonAn<>i.MaMonAn
 )
  THROW 51104,N'Phải xóa tùy biến cũ trước khi đổi món.',1;
END;
GO

CREATE OR ALTER TRIGGER dbo.TrgThucDonKiemTraKhoangNgay
ON dbo.ThucDon AFTER UPDATE,DELETE
AS
BEGIN
 IF ROWCOUNT_BIG()=0 RETURN;
 SET NOCOUNT ON;

 IF UPDATE(MaThucDon)
  THROW 51105,N'Mã thực đơn là bất biến.',1;

 IF EXISTS(
    SELECT 1
    FROM inserted i
    JOIN deleted d ON i.MaThucDon=d.MaThucDon
    WHERE i.MaNguoiDung<>d.MaNguoiDung
 )
  THROW 51106,N'Không được đổi chủ sở hữu thực đơn.',1;

 IF EXISTS(
    SELECT 1
    FROM deleted
    WHERE TrangThai=N'Đã kết thúc'
 )
  THROW 51107,N'Thực đơn đã kết thúc được giữ nguyên lịch sử.',1;

 IF EXISTS(
    SELECT 1
    FROM inserted i
    JOIN dbo.ChiTietThucDon ct WITH(UPDLOCK,HOLDLOCK)
      ON ct.MaThucDon=i.MaThucDon
    WHERE ct.NgayDung NOT BETWEEN i.NgayBatDau AND i.NgayKetThuc
 )
  THROW 50030,N'Khoảng ngày mới làm chi tiết nằm ngoài phạm vi.',1;
END;
GO

CREATE OR ALTER TRIGGER dbo.TrgCongThucCongBo
ON dbo.CongThuc AFTER INSERT,UPDATE,DELETE
AS
BEGIN
 IF ROWCOUNT_BIG()=0 RETURN;
 SET NOCOUNT ON;

 IF EXISTS(
    SELECT 1
    FROM deleted d
    WHERE NOT EXISTS(
        SELECT 1 FROM inserted i
        WHERE i.MaCongThuc=d.MaCongThuc
    )
    AND (
        d.DaCongBo=1
        OR EXISTS(
            SELECT 1
            FROM dbo.ChiTietThucDon ct WITH(UPDLOCK,HOLDLOCK)
            WHERE ct.MaMonAn=d.MaMonAn
        )
    )
 )
 THROW 51120,N'Không xóa công thức công bố hoặc món đang có trong thực đơn.',1;

 IF UPDATE(MaCongThuc) AND EXISTS(SELECT 1 FROM deleted)
 THROW 51119,N'Mã công thức là bất biến.',1;

 IF EXISTS(
    SELECT 1
    FROM inserted i
    JOIN deleted d ON i.MaCongThuc=d.MaCongThuc
    WHERE i.MaMonAn<>d.MaMonAn
 )
 THROW 51108,N'Công thức không được chuyển sang món khác.',1;

 IF EXISTS(
    SELECT 1
    FROM inserted i
    WHERE i.DaCongBo=1
    AND (
        NOT EXISTS(
            SELECT 1
            FROM dbo.ThanhPhanCongThuc tp WITH(UPDLOCK,HOLDLOCK)
            WHERE tp.MaCongThuc=i.MaCongThuc
        )
        OR NOT EXISTS(
            SELECT 1
            FROM dbo.BuocCheBien b WITH(UPDLOCK,HOLDLOCK)
            WHERE b.MaCongThuc=i.MaCongThuc
        )
    )
 )
 THROW 51109,N'Công thức công bố phải có ít nhất một nguyên liệu và một bước.',1;
END;
GO

CREATE OR ALTER TRIGGER dbo.TrgThanhPhanBaoVeCongThuc
ON dbo.ThanhPhanCongThuc AFTER INSERT,UPDATE,DELETE
AS
BEGIN
 IF ROWCOUNT_BIG()=0 RETURN;
 SET NOCOUNT ON;

 IF UPDATE(MaThanhPhan) AND EXISTS(SELECT 1 FROM deleted)
 THROW 51119,N'Mã thành phần là bất biến.',1;

 DECLARE @LockCount BIGINT;

 SELECT @LockCount=COUNT_BIG(*)
 FROM dbo.CongThuc c WITH(UPDLOCK,HOLDLOCK)
 WHERE c.MaCongThuc IN(
    SELECT MaCongThuc FROM inserted
    UNION
    SELECT MaCongThuc FROM deleted
 );

 IF EXISTS(
    SELECT 1
    FROM inserted i
    JOIN deleted d ON i.MaThanhPhan=d.MaThanhPhan
    WHERE i.MaCongThuc<>d.MaCongThuc
 )
 THROW 51110,N'Thành phần không được chuyển sang công thức khác.',1;

 IF EXISTS(
    SELECT 1
    FROM dbo.CongThuc c
    WHERE c.DaCongBo=1
      AND c.MaCongThuc IN(SELECT MaCongThuc FROM deleted)
      AND NOT EXISTS(
          SELECT 1
          FROM dbo.ThanhPhanCongThuc tp WITH(UPDLOCK,HOLDLOCK)
          WHERE tp.MaCongThuc=c.MaCongThuc
      )
 )
 THROW 51111,N'Không được xóa hết thành phần của công thức đã công bố.',1;
END;
GO

CREATE OR ALTER TRIGGER dbo.TrgBuocCheBienBaoVeCongThuc
ON dbo.BuocCheBien AFTER INSERT,UPDATE,DELETE
AS
BEGIN
 IF ROWCOUNT_BIG()=0 RETURN;
 SET NOCOUNT ON;

 IF UPDATE(MaBuoc) AND EXISTS(SELECT 1 FROM deleted)
 THROW 51119,N'Mã bước là bất biến.',1;

 DECLARE @LockCount BIGINT;

 SELECT @LockCount=COUNT_BIG(*)
 FROM dbo.CongThuc c WITH(UPDLOCK,HOLDLOCK)
 WHERE c.MaCongThuc IN(
    SELECT MaCongThuc FROM inserted
    UNION
    SELECT MaCongThuc FROM deleted
 );

 IF EXISTS(
    SELECT 1
    FROM inserted i
    JOIN deleted d ON i.MaBuoc=d.MaBuoc
    WHERE i.MaCongThuc<>d.MaCongThuc
 )
 THROW 51112,N'Bước chế biến không được chuyển sang công thức khác.',1;

 IF EXISTS(
    SELECT 1
    FROM dbo.CongThuc c
    WHERE c.DaCongBo=1
      AND c.MaCongThuc IN(SELECT MaCongThuc FROM deleted)
      AND NOT EXISTS(
          SELECT 1
          FROM dbo.BuocCheBien b WITH(UPDLOCK,HOLDLOCK)
          WHERE b.MaCongThuc=c.MaCongThuc
      )
 )
 THROW 51113,N'Không được xóa hết bước của công thức đã công bố.',1;
END;
GO

CREATE OR ALTER TRIGGER dbo.TrgTuyBienKiemTraLienKet
ON dbo.TuyBienNguyenLieuThucDon AFTER INSERT,UPDATE,DELETE
AS
BEGIN
 IF ROWCOUNT_BIG()=0 RETURN;
 SET NOCOUNT ON;

 DECLARE @LockCount BIGINT;

 SELECT @LockCount=COUNT_BIG(*)
 FROM dbo.ThucDon td WITH(UPDLOCK,HOLDLOCK)
 JOIN dbo.ChiTietThucDon ct ON ct.MaThucDon=td.MaThucDon
 WHERE ct.MaChiTiet IN(
    SELECT MaChiTiet FROM inserted
    UNION
    SELECT MaChiTiet FROM deleted
 );

 IF EXISTS(
    SELECT 1
    FROM inserted i
    JOIN dbo.ChiTietThucDon ct
      ON ct.MaChiTiet=i.MaChiTiet
    JOIN dbo.ThanhPhanCongThuc tp
      ON tp.MaThanhPhan=i.MaThanhPhan
    JOIN dbo.CongThuc c
      ON c.MaCongThuc=tp.MaCongThuc
    WHERE c.MaMonAn<>ct.MaMonAn
 )
 THROW 51114,N'Tùy biến phải thuộc đúng công thức của món trong thực đơn.',1;

 IF EXISTS(
    SELECT 1
    FROM dbo.ThucDon td
    JOIN dbo.ChiTietThucDon ct
      ON ct.MaThucDon=td.MaThucDon
    WHERE td.TrangThai=N'Đã kết thúc'
      AND ct.MaChiTiet IN(
          SELECT MaChiTiet FROM inserted
          UNION
          SELECT MaChiTiet FROM deleted
      )
 )
 THROW 51115,N'Không được tùy biến thực đơn đã kết thúc.',1;
END;
GO

CREATE OR ALTER TRIGGER dbo.TrgMonYeuThichKhongMauThuan
ON dbo.MonYeuThich AFTER INSERT,UPDATE
AS
BEGIN
