 DECLARE @LockCount BIGINT;

 SELECT @LockCount=COUNT_BIG(*)
 FROM dbo.NguoiDung u WITH(UPDLOCK,HOLDLOCK)
 WHERE MaNguoiDung IN(SELECT MaNguoiDung FROM inserted);

 IF EXISTS(
    SELECT 1
    FROM inserted i
    JOIN dbo.MonKhongThich x WITH(UPDLOCK,HOLDLOCK)
      ON x.MaNguoiDung=i.MaNguoiDung
     AND x.MaMonAn=i.MaMonAn
 )
 THROW 51116,N'Món không thể vừa yêu thích vừa không thích.',1;
END;
GO

