-- BỔ SUNG CRUD CÓ KIỂM SOÁT

-- Đọc năm danh mục theo loại cố định và mã tùy chọn; không dùng dynamic SQL.
CREATE OR ALTER PROCEDURE dbo.SpLayDanhMuc
 @Loai NVARCHAR(30),
 @Ma NVARCHAR(20)=NULL
AS
BEGIN
 SET NOCOUNT ON;

 IF @Loai IS NULL OR LEN(LTRIM(RTRIM(@Loai)))=0
 THROW 51200,N'@Loai không được rỗng.',1;

 IF @Loai NOT IN(
    N'DanhMucMonAn',
    N'NguyenLieu',
    N'KhauVi',
    N'CheDoAn',
    N'DonViTinh'
 )
 THROW 51201,N'Loại danh mục không hợp lệ.',1;

 IF @Loai=N'DanhMucMonAn'
  SELECT MaDanhMuc,TenDanhMuc,MoTa
  FROM dbo.DanhMucMonAn
  WHERE @Ma IS NULL OR MaDanhMuc=@Ma
  ORDER BY TenDanhMuc,MaDanhMuc;

 IF @Loai=N'NguyenLieu'
  SELECT MaNguyenLieu,TenNguyenLieu,MoTa
  FROM dbo.NguyenLieu
  WHERE @Ma IS NULL OR MaNguyenLieu=@Ma
  ORDER BY TenNguyenLieu,MaNguyenLieu;

 IF @Loai=N'KhauVi'
  SELECT MaKhauVi,TenKhauVi,MoTa
  FROM dbo.KhauVi
  WHERE @Ma IS NULL OR MaKhauVi=@Ma
  ORDER BY TenKhauVi,MaKhauVi;

 IF @Loai=N'CheDoAn'
  SELECT MaCheDoAn,TenCheDoAn,MoTa
  FROM dbo.CheDoAn
  WHERE @Ma IS NULL OR MaCheDoAn=@Ma
  ORDER BY TenCheDoAn,MaCheDoAn;

 IF @Loai=N'DonViTinh'
  SELECT MaDonVi,TenDonVi,KyHieu,HeSoGramChuan
  FROM dbo.DonViTinh
  WHERE @Ma IS NULL OR MaDonVi=@Ma
  ORDER BY TenDonVi,MaDonVi;
END;
GO

-- Xóa danh mục chưa được tham chiếu; FK chặn xóa bản ghi đang sử dụng.
CREATE OR ALTER PROCEDURE dbo.SpXoaDanhMuc
 @MaQuanTri NVARCHAR(20),
 @Loai NVARCHAR(30),
 @Ma NVARCHAR(20)
AS
BEGIN
 SET NOCOUNT ON;
 SET XACT_ABORT ON;

 DECLARE @TranBanDau INT=@@TRANCOUNT;

 BEGIN TRY
  IF @TranBanDau=0 BEGIN TRANSACTION;
  ELSE SAVE TRANSACTION CrudSave;

  IF @MaQuanTri IS NULL OR LEN(LTRIM(RTRIM(@MaQuanTri)))=0
   THROW 51200,N'@MaQuanTri không được rỗng.',1;

  IF @Loai IS NULL OR LEN(LTRIM(RTRIM(@Loai)))=0
   THROW 51200,N'@Loai không được rỗng.',1;

  IF @Ma IS NULL OR LEN(LTRIM(RTRIM(@Ma)))=0
   THROW 51200,N'@Ma không được rỗng.',1;

  EXEC dbo.SpKiemTraQuanTri @MaQuanTri;

  IF @Loai NOT IN(
      N'DanhMucMonAn',
      N'NguyenLieu',
      N'KhauVi',
      N'CheDoAn',
      N'DonViTinh'
  )
   THROW 51201,N'Loại danh mục không hợp lệ.',1;

  DECLARE @SoDong INT=0;

  IF @Loai=N'DanhMucMonAn'
  BEGIN
   DELETE dbo.DanhMucMonAn WHERE MaDanhMuc=@Ma;
   SET @SoDong=@@ROWCOUNT;
  END;

  IF @Loai=N'NguyenLieu'
  BEGIN
   DELETE dbo.NguyenLieu WHERE MaNguyenLieu=@Ma;
   SET @SoDong=@@ROWCOUNT;
  END;

  IF @Loai=N'KhauVi'
  BEGIN
   DELETE dbo.KhauVi WHERE MaKhauVi=@Ma;
   SET @SoDong=@@ROWCOUNT;
  END;

  IF @Loai=N'CheDoAn'
  BEGIN
   DELETE dbo.CheDoAn WHERE MaCheDoAn=@Ma;
   SET @SoDong=@@ROWCOUNT;
  END;

  IF @Loai=N'DonViTinh'
  BEGIN
   DELETE dbo.DonViTinh WHERE MaDonVi=@Ma;
   SET @SoDong=@@ROWCOUNT;
  END;

  IF @SoDong=0
   THROW 51202,N'Không tìm thấy bản ghi cần xóa.',1;

  IF @TranBanDau=0 COMMIT TRANSACTION;
 END TRY
 BEGIN CATCH
  IF @TranBanDau=0 AND XACT_STATE()<>0
   ROLLBACK TRANSACTION;
  ELSE IF @TranBanDau>0 AND XACT_STATE()=1
   ROLLBACK TRANSACTION CrudSave;
  THROW;
 END CATCH;
END;
GO

-- Đọc hồ sơ và sáu nhóm tùy chọn cá nhân; không trả hash mật khẩu.
CREATE OR ALTER PROCEDURE dbo.SpLayThongTinCaNhan
 @MaNguoiDung NVARCHAR(20)
AS
BEGIN
 SET NOCOUNT ON;

 IF @MaNguoiDung IS NULL OR LEN(LTRIM(RTRIM(@MaNguoiDung)))=0
  THROW 51200,N'@MaNguoiDung không được rỗng.',1;

 EXEC dbo.SpKiemTraNguoiDungHoatDong @MaNguoiDung;

 SELECT MaNguoiDung,HoTen,ThuDienTu,VaiTro,TrangThai
 FROM dbo.NguoiDung
 WHERE MaNguoiDung=@MaNguoiDung;

 SELECT s.MaSoThichKhauVi,k.MaKhauVi,k.TenKhauVi
 FROM dbo.SoThichKhauVi s
 JOIN dbo.KhauVi k ON k.MaKhauVi=s.MaKhauVi
 WHERE s.MaNguoiDung=@MaNguoiDung
 ORDER BY k.TenKhauVi;

 SELECT u.MaCheDoAnNguoiDung,c.MaCheDoAn,c.TenCheDoAn
 FROM dbo.CheDoAnNguoiDung u
 JOIN dbo.CheDoAn c ON c.MaCheDoAn=u.MaCheDoAn
 WHERE u.MaNguoiDung=@MaNguoiDung
 ORDER BY c.TenCheDoAn;

 SELECT *
 FROM dbo.MucTieuDinhDuong
 WHERE MaNguoiDung=@MaNguoiDung;

 SELECT *
 FROM dbo.NganSachAnUong
 WHERE MaNguoiDung=@MaNguoiDung
 ORDER BY NgayBatDau,MaNganSach;

 SELECT y.MaMonYeuThich,y.MaMonAn,m.TenMonAn,y.NgayThem
 FROM dbo.MonYeuThich y
 JOIN dbo.MonAn m ON m.MaMonAn=y.MaMonAn
 WHERE y.MaNguoiDung=@MaNguoiDung
 ORDER BY y.NgayThem DESC,y.MaMonAn;

 SELECT y.MaMonAn,m.TenMonAn,y.NgayThem
 FROM dbo.MonKhongThich y
 JOIN dbo.MonAn m ON m.MaMonAn=y.MaMonAn
 WHERE y.MaNguoiDung=@MaNguoiDung
 ORDER BY y.NgayThem DESC,y.MaMonAn;
END;
GO

-- Quản trị đọc danh sách/hồ sơ tài khoản, không trả hash.
CREATE OR ALTER PROCEDURE dbo.SpLayNguoiDung
 @MaQuanTri NVARCHAR(20),
 @MaNguoiDung NVARCHAR(20)=NULL
AS
BEGIN
 SET NOCOUNT ON;

 IF @MaQuanTri IS NULL OR LEN(LTRIM(RTRIM(@MaQuanTri)))=0
  THROW 51200,N'@MaQuanTri không được rỗng.',1;

 EXEC dbo.SpKiemTraQuanTri @MaQuanTri;

 SELECT MaNguoiDung,HoTen,ThuDienTu,VaiTro,TrangThai
 FROM dbo.NguoiDung
 WHERE @MaNguoiDung IS NULL OR MaNguoiDung=@MaNguoiDung
 ORDER BY MaNguoiDung;
END;
GO

-- Khóa/mở tài khoản thay cho xóa cứng lịch sử; không đổi vai trò và không tự khóa quản trị.
CREATE OR ALTER PROCEDURE dbo.SpDatTrangThaiNguoiDung
 @MaQuanTri NVARCHAR(20),
 @MaNguoiDung NVARCHAR(20),
 @TrangThai NVARCHAR(30)
AS
BEGIN
 SET NOCOUNT ON;
 SET XACT_ABORT ON;

 DECLARE @TranBanDau INT=@@TRANCOUNT;

 BEGIN TRY
  IF @TranBanDau=0 BEGIN TRANSACTION;
  ELSE SAVE TRANSACTION CrudSave;

  IF @MaQuanTri IS NULL OR LEN(LTRIM(RTRIM(@MaQuanTri)))=0
   THROW 51200,N'@MaQuanTri không được rỗng.',1;

  IF @MaNguoiDung IS NULL OR LEN(LTRIM(RTRIM(@MaNguoiDung)))=0
   THROW 51200,N'@MaNguoiDung không được rỗng.',1;

  IF @TrangThai IS NULL OR LEN(LTRIM(RTRIM(@TrangThai)))=0
   THROW 51200,N'@TrangThai không được rỗng.',1;

  EXEC dbo.SpKiemTraQuanTri @MaQuanTri;

  IF @TrangThai NOT IN(N'Đang hoạt động',N'Tạm khóa')
   THROW 51203,N'Trạng thái tài khoản không hợp lệ.',1;

  IF @MaQuanTri=@MaNguoiDung AND @TrangThai=N'Tạm khóa'
   THROW 51204,N'Không tự khóa tài khoản quản trị đang sử dụng.',1;

  UPDATE dbo.NguoiDung
  SET TrangThai=@TrangThai
  WHERE MaNguoiDung=@MaNguoiDung;

  IF @@ROWCOUNT=0
   THROW 51202,N'Không tìm thấy tài khoản.',1;

  IF @TranBanDau=0 COMMIT TRANSACTION;
 END TRY
 BEGIN CATCH
  IF @TranBanDau=0 AND XACT_STATE()<>0
   ROLLBACK TRANSACTION;
  ELSE IF @TranBanDau>0 AND XACT_STATE()=1
   ROLLBACK TRANSACTION CrudSave;
  THROW;
 END CATCH;
END;
GO

-- Xóa món chưa có bất kỳ tham chiếu; FK chặn nếu còn công thức/menu/đánh giá/liên kết.
CREATE OR ALTER PROCEDURE dbo.SpXoaMonAn
 @MaQuanTri NVARCHAR(20),
 @MaMonAn NVARCHAR(20)
AS
BEGIN
 SET NOCOUNT ON;
 SET XACT_ABORT ON;

 DECLARE @TranBanDau INT=@@TRANCOUNT;

 BEGIN TRY
  IF @TranBanDau=0 BEGIN TRANSACTION;
  ELSE SAVE TRANSACTION CrudSave;

  IF @MaQuanTri IS NULL OR LEN(LTRIM(RTRIM(@MaQuanTri)))=0
   THROW 51200,N'@MaQuanTri không được rỗng.',1;

  IF @MaMonAn IS NULL OR LEN(LTRIM(RTRIM(@MaMonAn)))=0
   THROW 51200,N'@MaMonAn không được rỗng.',1;

  EXEC dbo.SpKiemTraQuanTri @MaQuanTri;

  DELETE dbo.MonAn
  WHERE MaMonAn=@MaMonAn;

  IF @@ROWCOUNT=0
   THROW 51202,N'Không tìm thấy món.',1;

  IF @TranBanDau=0 COMMIT TRANSACTION;
 END TRY
 BEGIN CATCH
  IF @TranBanDau=0 AND XACT_STATE()<>0
   ROLLBACK TRANSACTION;
  ELSE IF @TranBanDau>0 AND XACT_STATE()=1
   ROLLBACK TRANSACTION CrudSave;
  THROW;
 END CATCH;
END;
GO

-- Xóa trọn công thức nháp và các con trong một giao dịch khi chưa dùng trong menu/chưa có phản hồi.
CREATE OR ALTER PROCEDURE dbo.SpXoaCongThuc
 @MaQuanTri NVARCHAR(20),
 @MaCongThuc NVARCHAR(20)
AS
BEGIN
 SET NOCOUNT ON;
 SET XACT_ABORT ON;

 DECLARE @TranBanDau INT=@@TRANCOUNT;

 BEGIN TRY
  IF @TranBanDau=0 BEGIN TRANSACTION;
  ELSE SAVE TRANSACTION CrudSave;

  IF @MaQuanTri IS NULL OR LEN(LTRIM(RTRIM(@MaQuanTri)))=0
   THROW 51200,N'@MaQuanTri không được rỗng.',1;

  IF @MaCongThuc IS NULL OR LEN(LTRIM(RTRIM(@MaCongThuc)))=0
   THROW 51200,N'@MaCongThuc không được rỗng.',1;

  EXEC dbo.SpKiemTraQuanTri @MaQuanTri;

  DECLARE @MaMon NVARCHAR(20);

  SELECT @MaMon=MaMonAn
  FROM dbo.CongThuc WITH(UPDLOCK,HOLDLOCK)
  WHERE MaCongThuc=@MaCongThuc;

  IF @MaMon IS NULL
   THROW 51202,N'Không tìm thấy công thức.',1;

  IF EXISTS(
      SELECT 1
      FROM dbo.CongThuc
      WHERE MaCongThuc=@MaCongThuc
        AND DaCongBo=1
  )
   THROW 51205,N'Chỉ xóa công thức nháp.',1;

  IF EXISTS(
      SELECT 1
      FROM dbo.ChiTietThucDon WITH(UPDLOCK,HOLDLOCK)
      WHERE MaMonAn=@MaMon
  )
   THROW 51206,N'Món đã có trong thực đơn; giữ công thức để tránh mất dữ liệu tham chiếu.',1;

  IF EXISTS(
      SELECT 1
      FROM dbo.PhanHoiCheBien WITH(UPDLOCK,HOLDLOCK)
      WHERE MaCongThuc=@MaCongThuc
  )
   THROW 51207,N'Công thức đã có phản hồi, không xóa lịch sử liên quan.',1;

  DELETE dbo.DoanPhimHuongDan
  WHERE MaCongThuc=@MaCongThuc;

  DELETE dbo.BuocCheBien
  WHERE MaCongThuc=@MaCongThuc;

  DELETE dbo.ThanhPhanCongThuc
  WHERE MaCongThuc=@MaCongThuc;

  DELETE dbo.CongThuc
  WHERE MaCongThuc=@MaCongThuc;

  IF @TranBanDau=0 COMMIT TRANSACTION;
 END TRY
 BEGIN CATCH
  IF @TranBanDau=0 AND XACT_STATE()<>0
   ROLLBACK TRANSACTION;
  ELSE IF @TranBanDau>0 AND XACT_STATE()=1
   ROLLBACK TRANSACTION CrudSave;
  THROW;
 END CATCH;
END;
GO

-- Xóa thành phần đúng công thức; trigger chặn xóa thành phần cuối của công thức công bố.
CREATE OR ALTER PROCEDURE dbo.SpXoaThanhPhanCongThuc
 @MaQuanTri NVARCHAR(20),
 @MaCongThuc NVARCHAR(20),
 @MaThanhPhan NVARCHAR(20)
AS
BEGIN
 SET NOCOUNT ON;
 SET XACT_ABORT ON;

 DECLARE @TranBanDau INT=@@TRANCOUNT;

 BEGIN TRY
  IF @TranBanDau=0 BEGIN TRANSACTION;
  ELSE SAVE TRANSACTION CrudSave;

  IF @MaQuanTri IS NULL OR LEN(LTRIM(RTRIM(@MaQuanTri)))=0
   THROW 51200,N'@MaQuanTri không được rỗng.',1;

  IF @MaCongThuc IS NULL OR LEN(LTRIM(RTRIM(@MaCongThuc)))=0
   THROW 51200,N'@MaCongThuc không được rỗng.',1;

  IF @MaThanhPhan IS NULL OR LEN(LTRIM(RTRIM(@MaThanhPhan)))=0
