-- Đọc danh sách đánh giá sao của một món.
CREATE OR ALTER PROCEDURE dbo.SpLayDanhGiaMonAn
 @MaMonAn NVARCHAR(20)
AS
BEGIN
 SET NOCOUNT ON;

 IF @MaMonAn IS NULL OR LEN(LTRIM(RTRIM(@MaMonAn)))=0
  THROW 51200,N'@MaMonAn không được rỗng.',1;

 IF NOT EXISTS(
     SELECT 1
     FROM dbo.MonAn
     WHERE MaMonAn=@MaMonAn
 )
  THROW 50006,N'Món ăn không tồn tại.',1;

 SELECT
  g.MaDanhGia,
  g.MaNguoiDung,
  u.HoTen,
  g.SoSao,
  g.NoiDung,
  g.NgayDanhGia
 FROM dbo.DanhGiaMonAn g
 JOIN dbo.NguoiDung u
   ON u.MaNguoiDung=g.MaNguoiDung
 WHERE g.MaMonAn=@MaMonAn
 ORDER BY g.NgayDanhGia DESC,g.MaDanhGia;
END;
GO

-- Xóa menu chưa kết thúc/chưa có snapshot cùng chi tiết và tùy biến; kiểm tra chủ và dùng một giao dịch.
CREATE OR ALTER PROCEDURE dbo.SpXoaThucDon
 @MaNguoiDung NVARCHAR(20),@MaThucDon NVARCHAR(20)
AS
BEGIN
 SET NOCOUNT ON;
 SET XACT_ABORT ON;

 DECLARE @TranBanDau INT=@@TRANCOUNT;

 BEGIN TRY
  IF @TranBanDau=0 BEGIN TRANSACTION;
  ELSE SAVE TRANSACTION CrudSave;

  IF @MaNguoiDung IS NULL OR LEN(LTRIM(RTRIM(@MaNguoiDung)))=0
   THROW 51200,N'@MaNguoiDung không được rỗng.',1;

  IF @MaThucDon IS NULL OR LEN(LTRIM(RTRIM(@MaThucDon)))=0
   THROW 51200,N'@MaThucDon không được rỗng.',1;

  EXEC dbo.SpKiemTraChuThucDon @MaNguoiDung,@MaThucDon;

  IF EXISTS(
      SELECT 1
      FROM dbo.DanhGiaDinhDuongThucDon WITH(UPDLOCK,HOLDLOCK)
      WHERE MaThucDon=@MaThucDon
  )
   THROW 51208,N'Thực đơn đã có lịch sử đánh giá; không xóa. Có thể chuyển sang đã kết thúc.',1;

  DELETE tb
  FROM dbo.TuyBienNguyenLieuThucDon tb
  JOIN dbo.ChiTietThucDon ct
    ON ct.MaChiTiet=tb.MaChiTiet
  WHERE ct.MaThucDon=@MaThucDon;

  DELETE dbo.ChiTietThucDon
  WHERE MaThucDon=@MaThucDon;

  DELETE dbo.ThucDon
  WHERE MaThucDon=@MaThucDon;

  IF @TranBanDau=0 COMMIT TRANSACTION;
   END TRY
 BEGIN CATCH
  IF @TranBanDau=0 AND XACT_STATE()<>0
   ROLLBACK TRANSACTION;
  ELSE IF @TranBanDau>0 AND XACT_STATE()=1
   ROLLBACK TRANSACTION CrudSave;
  THROW;
 END CATCH;
END;
GO

-- Đọc các lần phản hồi của người dùng, lọc công thức tùy chọn.
CREATE OR ALTER PROCEDURE dbo.SpLayPhanHoiCheBien
 @MaNguoiDung NVARCHAR(20),
 @MaCongThuc NVARCHAR(20)=NULL
AS
BEGIN
 SET NOCOUNT ON;

 IF @MaNguoiDung IS NULL OR LEN(LTRIM(RTRIM(@MaNguoiDung)))=0
  THROW 51200,N'@MaNguoiDung không được rỗng.',1;

 EXEC dbo.SpKiemTraNguoiDungHoatDong @MaNguoiDung;

 SELECT *
 FROM dbo.PhanHoiCheBien
 WHERE MaNguoiDung=@MaNguoiDung
   AND (@MaCongThuc IS NULL OR MaCongThuc=@MaCongThuc)
 ORDER BY ThoiDiemNau DESC,MaPhanHoi;
END;
GO

-- Sửa nội dung/kết quả/thời điểm phản hồi của chính người dùng; không đổi người hoặc công thức.
CREATE OR ALTER PROCEDURE dbo.SpCapNhatPhanHoiCheBien
 @MaNguoiDung NVARCHAR(20),
 @MaPhanHoi NVARCHAR(20),
 @ThoiDiemNau DATETIME2(0),
 @ThanhCong BIT,
 @NoiDung NVARCHAR(1500)
AS
BEGIN
 SET NOCOUNT ON;
 SET XACT_ABORT ON;

 DECLARE @TranBanDau INT=@@TRANCOUNT;

 BEGIN TRY
  IF @TranBanDau=0 BEGIN TRANSACTION;
  ELSE SAVE TRANSACTION CrudSave;

  IF @MaNguoiDung IS NULL OR LEN(LTRIM(RTRIM(@MaNguoiDung)))=0
   THROW 51200,N'@MaNguoiDung không được rỗng.',1;

  IF @MaPhanHoi IS NULL OR LEN(LTRIM(RTRIM(@MaPhanHoi)))=0
   THROW 51200,N'@MaPhanHoi không được rỗng.',1;

  IF @NoiDung IS NULL OR LEN(LTRIM(RTRIM(@NoiDung)))=0
   THROW 51200,N'@NoiDung không được rỗng.',1;

  EXEC dbo.SpKiemTraNguoiDungHoatDong @MaNguoiDung;

  IF @ThoiDiemNau IS NULL
     OR @ThoiDiemNau>CONVERT(DATETIME2(0),SYSUTCDATETIME())
   THROW 51028,N'Thời điểm nấu không hợp lệ (UTC).',1;

  IF @ThanhCong IS NULL
   THROW 51209,N'Kết quả nấu không được NULL.',1;

  UPDATE dbo.PhanHoiCheBien
  SET ThoiDiemNau=@ThoiDiemNau,
      ThanhCong=@ThanhCong,
      NoiDung=@NoiDung
  WHERE MaPhanHoi=@MaPhanHoi
    AND MaNguoiDung=@MaNguoiDung;

  IF @@ROWCOUNT=0
   THROW 51202,N'Không tìm thấy phản hồi của người dùng.',1;

  IF @TranBanDau=0 COMMIT TRANSACTION;
 END TRY
 BEGIN CATCH
  IF @TranBanDau=0 AND XACT_STATE()<>0
   ROLLBACK TRANSACTION;
  ELSE IF @TranBanDau>0 AND XACT_STATE()=1
   ROLLBACK TRANSACTION CrudSave;
  THROW;
 END CATCH;
END;
GO

-- Đọc dinh dưỡng, quy đổi, lịch sử giá và gợi ý thay thế của nguyên liệu.
CREATE OR ALTER PROCEDURE dbo.SpLayDuLieuNguyenLieu
 @MaNguyenLieu NVARCHAR(20)
AS
BEGIN
 SET NOCOUNT ON;

 IF @MaNguyenLieu IS NULL OR LEN(LTRIM(RTRIM(@MaNguyenLieu)))=0
  THROW 51200,N'@MaNguyenLieu không được rỗng.',1;

 IF NOT EXISTS(
     SELECT 1
     FROM dbo.NguyenLieu
     WHERE MaNguyenLieu=@MaNguyenLieu
 )
  THROW 50002,N'Nguyên liệu không tồn tại.',1;

 SELECT *
 FROM dbo.ThongTinDinhDuong
 WHERE MaNguyenLieu=@MaNguyenLieu;

 SELECT *
 FROM dbo.QuyDoiDonViNguyenLieu
 WHERE MaNguyenLieu=@MaNguyenLieu
 ORDER BY MaDonVi;

 SELECT *
 FROM dbo.GiaNguyenLieu
 WHERE MaNguyenLieu=@MaNguyenLieu
 ORDER BY NgayApDung DESC,MaGia;

 SELECT
  tt.*,
  n.TenNguyenLieu AS TenThayThe
 FROM dbo.NguyenLieuThayThe tt
 JOIN dbo.NguyenLieu n
   ON n.MaNguyenLieu=tt.MaNguyenLieuThayThe
 WHERE tt.MaNguyenLieuGoc=@MaNguyenLieu
 ORDER BY tt.MaNguyenLieuThayThe;
END;
GO

-- Xóa dinh dưỡng/quy đổi/gợi ý thay thế hiện tại; phép tính mới có thể thiếu dữ liệu, snapshot cũ giữ nguyên.
CREATE OR ALTER PROCEDURE dbo.SpXoaDuLieuNguyenLieu
 @MaQuanTri NVARCHAR(20),
 @MaNguyenLieu NVARCHAR(20),
 @Loai NVARCHAR(30),
 @Ma NVARCHAR(20)
AS
BEGIN
 SET NOCOUNT ON;
 SET XACT_ABORT ON;

 DECLARE @TranBanDau INT=@@TRANCOUNT;

 BEGIN TRY
  IF @TranBanDau=0 BEGIN TRANSACTION;
  ELSE SAVE TRANSACTION CrudSave;

  IF @MaQuanTri IS NULL OR LEN(LTRIM(RTRIM(@MaQuanTri)))=0
   THROW 51200,N'@MaQuanTri không được rỗng.',1;

  IF @MaNguyenLieu IS NULL OR LEN(LTRIM(RTRIM(@MaNguyenLieu)))=0
   THROW 51200,N'@MaNguyenLieu không được rỗng.',1;

  IF @Loai IS NULL OR LEN(LTRIM(RTRIM(@Loai)))=0
   THROW 51200,N'@Loai không được rỗng.',1;

  IF @Ma IS NULL OR LEN(LTRIM(RTRIM(@Ma)))=0
   THROW 51200,N'@Ma không được rỗng.',1;

  EXEC dbo.SpKiemTraQuanTri @MaQuanTri;

  IF @Loai NOT IN(N'DinhDuong',N'QuyDoi',N'ThayThe')
   THROW 51210,N'Chỉ hỗ trợ DinhDuong, QuyDoi, ThayThe; lịch sử giá không xóa qua API này.',1;

  DECLARE @SoDong INT=0;

  IF @Loai=N'DinhDuong'
  BEGIN
   DELETE dbo.ThongTinDinhDuong
   WHERE MaThongTin=@Ma
     AND MaNguyenLieu=@MaNguyenLieu;

   SET @SoDong=@@ROWCOUNT;
  END;

  IF @Loai=N'QuyDoi'
  BEGIN
   DELETE dbo.QuyDoiDonViNguyenLieu
   WHERE MaQuyDoi=@Ma
     AND MaNguyenLieu=@MaNguyenLieu;

   SET @SoDong=@@ROWCOUNT;
  END;

  IF @Loai=N'ThayThe'
  BEGIN
   DELETE dbo.NguyenLieuThayThe
   WHERE MaThayThe=@Ma
     AND MaNguyenLieuGoc=@MaNguyenLieu;

   SET @SoDong=@@ROWCOUNT;
  END;

  IF @SoDong=0
   THROW 51202,N'Không tìm thấy dữ liệu của nguyên liệu.',1;

  IF @TranBanDau=0 COMMIT TRANSACTION;
 END TRY
 BEGIN CATCH
  IF @TranBanDau=0 AND XACT_STATE()<>0
   ROLLBACK TRANSACTION;
  ELSE IF @TranBanDau>0 AND XACT_STATE()=1
   ROLLBACK TRANSACTION CrudSave;
  THROW;
 END CATCH;
END;
GO

-- Tạo/sửa tỷ lệ gợi ý thay thế một chiều; CHECK chặn tự thay chính mình và tỷ lệ không dương.
CREATE OR ALTER PROCEDURE dbo.SpLuuNguyenLieuThayThe
 @MaQuanTri NVARCHAR(20),
 @MaThayThe NVARCHAR(20),
 @MaNguyenLieuGoc NVARCHAR(20),
 @MaNguyenLieuThayThe NVARCHAR(20),
 @TyLe DECIMAL(10,3)
AS
BEGIN
 SET NOCOUNT ON;
 SET XACT_ABORT ON;

 DECLARE @TranBanDau INT=@@TRANCOUNT;

 BEGIN TRY
  IF @TranBanDau=0 BEGIN TRANSACTION;
  ELSE SAVE TRANSACTION CrudSave;

  IF @MaQuanTri IS NULL OR LEN(LTRIM(RTRIM(@MaQuanTri)))=0
   THROW 51200,N'@MaQuanTri không được rỗng.',1;

  IF @MaThayThe IS NULL OR LEN(LTRIM(RTRIM(@MaThayThe)))=0
   THROW 51200,N'@MaThayThe không được rỗng.',1;

  IF @MaNguyenLieuGoc IS NULL OR LEN(LTRIM(RTRIM(@MaNguyenLieuGoc)))=0
   THROW 51200,N'@MaNguyenLieuGoc không được rỗng.',1;

  IF @MaNguyenLieuThayThe IS NULL OR LEN(LTRIM(RTRIM(@MaNguyenLieuThayThe)))=0
   THROW 51200,N'@MaNguyenLieuThayThe không được rỗng.',1;

  EXEC dbo.SpKiemTraQuanTri @MaQuanTri;

  IF EXISTS(
      SELECT 1
      FROM dbo.NguyenLieuThayThe WITH(UPDLOCK,HOLDLOCK)
      WHERE MaThayThe=@MaThayThe
        AND (
            MaNguyenLieuGoc<>@MaNguyenLieuGoc
            OR MaNguyenLieuThayThe<>@MaNguyenLieuThayThe
        )
  )
   THROW 51030,N'Mã thay thế đã thuộc cặp khác.',1;

  IF EXISTS(
      SELECT 1
      FROM dbo.NguyenLieuThayThe
      WHERE MaThayThe=@MaThayThe
  )
   UPDATE dbo.NguyenLieuThayThe
   SET TyLeQuyDoi=@TyLe
   WHERE MaThayThe=@MaThayThe;
  ELSE
   INSERT dbo.NguyenLieuThayThe
   (
    MaThayThe,
    MaNguyenLieuGoc,
    MaNguyenLieuThayThe,
    TyLeQuyDoi
   )
   VALUES
   (
    @MaThayThe,
    @MaNguyenLieuGoc,
    @MaNguyenLieuThayThe,
    @TyLe
   );

  IF @TranBanDau=0 COMMIT TRANSACTION;
 END TRY
 BEGIN CATCH
  IF @TranBanDau=0 AND XACT_STATE()<>0
   ROLLBACK TRANSACTION;
  ELSE IF @TranBanDau>0 AND XACT_STATE()=1
   ROLLBACK TRANSACTION CrudSave;
  THROW;
 END CATCH;
END;
GO

/* Dinh dưỡng bổ sung: dữ liệu theo 100 ml nước mắm và 100 g tiêu đen xay.
