/* ============================================================
   BƯỚC 1: CẬP NHẬT RÀNG BUỘC VAI TRÒ
   Không thay đổi dữ liệu NguoiDung hiện tại
   ============================================================ */

DECLARE @TenConstraint SYSNAME;

/* Tìm CHECK constraint hiện tại có liên quan đến cột VaiTro */
SELECT TOP 1
    @TenConstraint = cc.name
FROM sys.check_constraints cc
JOIN sys.tables t
    ON cc.parent_object_id = t.object_id
WHERE t.name = N'NguoiDung'
  AND SCHEMA_NAME(t.schema_id) = N'dbo'
  AND cc.definition LIKE N'%VaiTro%';

IF @TenConstraint IS NOT NULL
BEGIN
    DECLARE @SQL NVARCHAR(MAX);

    SET @SQL =
        N'ALTER TABLE dbo.NguoiDung DROP CONSTRAINT '
        + QUOTENAME(@TenConstraint) + N';';

    EXEC sp_executesql @SQL;

    PRINT N'Đã xóa CHECK constraint VaiTro cũ: ' + @TenConstraint;
END;
ELSE
BEGIN
    PRINT N'Không tìm thấy CHECK constraint VaiTro cũ.';
END;
GO


/* Tạm thời chấp nhận cả role cũ và role mới.
   Mục đích: không làm hỏng dữ liệu hiện tại trong quá trình migration. */
ALTER TABLE dbo.NguoiDung
ADD CONSTRAINT CK_NguoiDung_VaiTro
CHECK
(
    VaiTro IN
    (
        N'Người dùng',
        N'Quản trị viên',       -- role cũ, tạm giữ
        N'Quản trị nội dung',
        N'Quản trị hệ thống'
    )
);
GO


USE QuanLyThucDon;
GO

/* ============================================================
   QUẢN TRỊ NỘI DUNG
   ============================================================ */

CREATE OR ALTER PROCEDURE dbo.SpKiemTraQuanTriNoiDung
    @MaQuanTri NVARCHAR(20)
AS
BEGIN
    SET NOCOUNT ON;

    IF @MaQuanTri IS NULL
    BEGIN
        THROW 51001, N'Mã quản trị không được để trống.', 1;
    END;

    IF NOT EXISTS
    (
        SELECT 1
        FROM dbo.NguoiDung
        WHERE MaNguoiDung = @MaQuanTri
          AND VaiTro = N'Quản trị nội dung'
          AND TrangThai = N'Đang hoạt động'
    )
    BEGIN
        THROW 51002,
              N'Chức năng này chỉ dành cho Quản trị nội dung đang hoạt động.',
              1;
    END;
END;
GO


/* ============================================================
   QUẢN TRỊ HỆ THỐNG
   ============================================================ */

CREATE OR ALTER PROCEDURE dbo.SpKiemTraQuanTriHeThong
    @MaQuanTri NVARCHAR(20)
AS
BEGIN
    SET NOCOUNT ON;

    IF @MaQuanTri IS NULL
    BEGIN
        THROW 51003, N'Mã quản trị không được để trống.', 1;
    END;

    IF NOT EXISTS
    (
        SELECT 1
        FROM dbo.NguoiDung
        WHERE MaNguoiDung = @MaQuanTri
          AND VaiTro = N'Quản trị hệ thống'
          AND TrangThai = N'Đang hoạt động'
    )
    BEGIN
        THROW 51004,
              N'Chức năng này chỉ dành cho Quản trị hệ thống đang hoạt động.',
              1;
    END;
END;
GO


CREATE OR ALTER PROCEDURE dbo.SpLayQuyenNguoiDung
    @MaNguoiDung NVARCHAR(20)
AS
BEGIN
    SET NOCOUNT ON;

    SELECT
        MaNguoiDung,
        HoTen,
        ThuDienTu,
        VaiTro,
        TrangThai,

        CAST(
            CASE
                WHEN VaiTro = N'Quản trị nội dung'
                     AND TrangThai = N'Đang hoạt động'
                THEN 1 ELSE 0
            END
        AS BIT) AS LaQuanTriNoiDung,

        CAST(
            CASE
                WHEN VaiTro = N'Quản trị hệ thống'
                     AND TrangThai = N'Đang hoạt động'
                THEN 1 ELSE 0
            END
        AS BIT) AS LaQuanTriHeThong

    FROM dbo.NguoiDung
    WHERE MaNguoiDung = @MaNguoiDung;
END;
GO


CREATE OR ALTER PROCEDURE dbo.SpDatVaiTroNguoiDung
    @MaQuanTri NVARCHAR(20),
    @MaNguoiDung NVARCHAR(20),
    @VaiTroMoi NVARCHAR(30)
AS
BEGIN
    SET NOCOUNT ON;
    SET XACT_ABORT ON;

    /* Chỉ Quản trị hệ thống được phân quyền */
    EXEC dbo.SpKiemTraQuanTriHeThong
         @MaQuanTri = @MaQuanTri;

    /* Không cho gán role cũ */
    IF @VaiTroMoi NOT IN
    (
        N'Người dùng',
        N'Quản trị nội dung',
        N'Quản trị hệ thống'
    )
    BEGIN
        THROW 51010, N'Vai trò mới không hợp lệ.', 1;
    END;

    /* Kiểm tra tài khoản đích */
    IF NOT EXISTS
    (
        SELECT 1
        FROM dbo.NguoiDung
        WHERE MaNguoiDung = @MaNguoiDung
    )
    BEGIN
        THROW 51011, N'Người dùng không tồn tại.', 1;
    END;

    /* Không cho quản trị hệ thống tự hạ quyền chính mình */
    IF @MaQuanTri = @MaNguoiDung
       AND @VaiTroMoi <> N'Quản trị hệ thống'
    BEGIN
        THROW 51012,
              N'Quản trị hệ thống không thể tự hạ quyền tài khoản đang sử dụng.',
              1;
    END;

    /* Không được làm mất quản trị hệ thống hoạt động cuối cùng */
    IF EXISTS
    (
        SELECT 1
        FROM dbo.NguoiDung
        WHERE MaNguoiDung = @MaNguoiDung
          AND VaiTro = N'Quản trị hệ thống'
          AND TrangThai = N'Đang hoạt động'
    )
    AND @VaiTroMoi <> N'Quản trị hệ thống'
    AND
    (
        SELECT COUNT(*)
        FROM dbo.NguoiDung
        WHERE VaiTro = N'Quản trị hệ thống'
          AND TrangThai = N'Đang hoạt động'
    ) <= 1
    BEGIN
        THROW 51013,
              N'Hệ thống phải còn ít nhất một Quản trị hệ thống đang hoạt động.',
              1;
    END;

    UPDATE dbo.NguoiDung
    SET VaiTro = @VaiTroMoi
    WHERE MaNguoiDung = @MaNguoiDung;

    SELECT
        MaNguoiDung,
        HoTen,
        ThuDienTu,
        VaiTro,
        TrangThai
    FROM dbo.NguoiDung
    WHERE MaNguoiDung = @MaNguoiDung;
END;
GO

/* 1. Kiểm tra role */
SELECT
    MaNguoiDung,
    HoTen,
    VaiTro,
    TrangThai
FROM dbo.NguoiDung
ORDER BY MaNguoiDung;


