FROM sys.check_constraints cc
WHERE cc.parent_object_id = OBJECT_ID(N'dbo.NguoiDung');


/* 3. Kiểm tra 3 procedure */
SELECT
    name
FROM sys.procedures
WHERE name IN
(
    N'SpKiemTraQuanTriNoiDung',
    N'SpKiemTraQuanTriHeThong',
    N'SpDatVaiTroNguoiDung',
    N'SpLayQuyenNguoiDung'
)
ORDER BY name;
GO

USE QuanLyThucDon;
