FROM sys.procedures p
JOIN sys.sql_modules sm
    ON sm.object_id = p.object_id
WHERE
(
       sm.definition LIKE N'%SpKiemTraQuanTri %'
    OR sm.definition LIKE N'%SpKiemTraQuanTri;%'
    OR sm.definition LIKE N'%SpKiemTraQuanTri@%'
)
AND p.name <> N'SpKiemTraQuanTri'
ORDER BY p.name;
GO

SELECT
    p.name AS TenProcedure,

    CASE
        WHEN sm.definition LIKE N'%SpKiemTraQuanTriNoiDung%'
            THEN N'Quản trị nội dung'

        WHEN sm.definition LIKE N'%SpKiemTraQuanTriHeThong%'
            THEN N'Quản trị hệ thống'

        WHEN sm.definition LIKE N'%SpKiemTraQuanTri%'
            THEN N'QUYỀN CŨ - CẦN KIỂM TRA'

        ELSE N'Không dùng kiểm tra quản trị'
    END AS PhanQuyen

FROM sys.procedures p
JOIN sys.sql_modules sm
    ON sm.object_id = p.object_id

ORDER BY
    PhanQuyen,
    p.name;
GO

