/* ============================================================
   1. KIỂM TRA QUẢN TRỊ CHUNG
   Giữ lại để tương thích với code cũ.
   KHÔNG dùng cho nghiệp vụ cần phân biệt quyền.
   ============================================================ */
CREATE OR ALTER PROCEDURE dbo.SpKiemTraQuanTri
    @MaQuanTri NVARCHAR(20)
AS
BEGIN
    SET NOCOUNT ON;

    IF @MaQuanTri IS NULL
       OR LEN(LTRIM(RTRIM(
            REPLACE(REPLACE(REPLACE(
                @MaQuanTri,
                NCHAR(9), N' '
            ), NCHAR(10), N' '), NCHAR(13), N' ')
       ))) = 0
    BEGIN
        THROW 51031, N'@MaQuanTri không được để trống.', 1;
    END;

    IF NOT EXISTS
    (
        SELECT 1
        FROM dbo.NguoiDung WITH (HOLDLOCK)
        WHERE MaNguoiDung = @MaQuanTri
          AND VaiTro IN
          (
              N'Quản trị nội dung',
              N'Quản trị hệ thống'
          )
          AND TrangThai = N'Đang hoạt động'
    )
    BEGIN
        THROW 51020,
              N'Cần tài khoản quản trị đang hoạt động.',
              1;
    END;
END;
GO


/* ============================================================
   2. SpLuuMonAn
   Chỉ QUẢN TRỊ NỘI DUNG
   ============================================================ */
CREATE OR ALTER PROCEDURE dbo.SpLuuMonAn
    @MaQuanTri NVARCHAR(20),
    @MaMonAn NVARCHAR(20),
    @MaDanhMuc NVARCHAR(20),
    @TenMonAn NVARCHAR(150),
    @ThoiGianCheBien INT,
    @DoKho NVARCHAR(30),
    @MoTa NVARCHAR(1000) = NULL,
    @DuongDanAnh NVARCHAR(500) = NULL
AS
BEGIN
    SET NOCOUNT ON;
    SET XACT_ABORT ON;

    DECLARE @TranBanDau INT = @@TRANCOUNT;

    BEGIN TRY

        IF @TranBanDau = 0
            BEGIN TRANSACTION;
        ELSE
            SAVE TRANSACTION ProcSave;

        IF @MaQuanTri IS NULL
           OR LEN(LTRIM(RTRIM(
                REPLACE(REPLACE(REPLACE(
                    @MaQuanTri,
                    NCHAR(9), N' '
                ), NCHAR(10), N' '), NCHAR(13), N' ')
           ))) = 0
            THROW 51031, N'@MaQuanTri không được để trống.', 1;

        IF @MaMonAn IS NULL
           OR LEN(LTRIM(RTRIM(
                REPLACE(REPLACE(REPLACE(
                    @MaMonAn,
                    NCHAR(9), N' '
                ), NCHAR(10), N' '), NCHAR(13), N' ')
           ))) = 0
            THROW 51031, N'@MaMonAn không được để trống.', 1;

        IF @MaDanhMuc IS NULL
           OR LEN(LTRIM(RTRIM(
                REPLACE(REPLACE(REPLACE(
                    @MaDanhMuc,
                    NCHAR(9), N' '
                ), NCHAR(10), N' '), NCHAR(13), N' ')
           ))) = 0
            THROW 51031, N'@MaDanhMuc không được để trống.', 1;

        IF @TenMonAn IS NULL
           OR LEN(LTRIM(RTRIM(
                REPLACE(REPLACE(REPLACE(
                    @TenMonAn,
                    NCHAR(9), N' '
                ), NCHAR(10), N' '), NCHAR(13), N' ')
           ))) = 0
            THROW 51031, N'@TenMonAn không được để trống.', 1;

        IF @DoKho IS NULL
           OR LEN(LTRIM(RTRIM(
                REPLACE(REPLACE(REPLACE(
                    @DoKho,
                    NCHAR(9), N' '
                ), NCHAR(10), N' '), NCHAR(13), N' ')
           ))) = 0
            THROW 51031, N'@DoKho không được để trống.', 1;


        /* QUYỀN MỚI */
        EXEC dbo.SpKiemTraQuanTriNoiDung
             @MaQuanTri = @MaQuanTri;


        IF EXISTS
        (
            SELECT 1
            FROM dbo.MonAn WITH (UPDLOCK, HOLDLOCK)
            WHERE MaMonAn = @MaMonAn
        )
        BEGIN
            UPDATE dbo.MonAn
            SET
                MaDanhMuc = @MaDanhMuc,
                TenMonAn = @TenMonAn,
                ThoiGianCheBien = @ThoiGianCheBien,
                DoKho = @DoKho,
                MoTa = @MoTa,
                DuongDanAnh = @DuongDanAnh
            WHERE MaMonAn = @MaMonAn;
        END
        ELSE
        BEGIN
            INSERT dbo.MonAn
            (
                MaMonAn,
                MaDanhMuc,
                TenMonAn,
                ThoiGianCheBien,
                DoKho,
                MoTa,
                DuongDanAnh
            )
            VALUES
            (
                @MaMonAn,
                @MaDanhMuc,
                @TenMonAn,
                @ThoiGianCheBien,
                @DoKho,
                @MoTa,
                @DuongDanAnh
            );
        END;

        IF @TranBanDau = 0
            COMMIT TRANSACTION;

    END TRY
    BEGIN CATCH

        IF @TranBanDau = 0
           AND XACT_STATE() <> 0
            ROLLBACK TRANSACTION;

        ELSE IF @TranBanDau > 0
            AND XACT_STATE() = 1
            ROLLBACK TRANSACTION ProcSave;

        THROW;

    END CATCH;
END;
GO


/* ============================================================
   3. SpLayNguoiDung
   Chỉ QUẢN TRỊ HỆ THỐNG
   ============================================================ */
CREATE OR ALTER PROCEDURE dbo.SpLayNguoiDung
    @MaQuanTri NVARCHAR(20),
    @MaNguoiDung NVARCHAR(20) = NULL
AS
BEGIN
    SET NOCOUNT ON;

    IF @MaQuanTri IS NULL
       OR LEN(LTRIM(RTRIM(@MaQuanTri))) = 0
    BEGIN
        THROW 51200, N'@MaQuanTri không được rỗng.', 1;
    END;


    EXEC dbo.SpKiemTraQuanTriHeThong
         @MaQuanTri = @MaQuanTri;


    SELECT
        MaNguoiDung,
        HoTen,
        ThuDienTu,
        VaiTro,
        TrangThai
    FROM dbo.NguoiDung
    WHERE @MaNguoiDung IS NULL
       OR MaNguoiDung = @MaNguoiDung
    ORDER BY MaNguoiDung;
END;
GO


/* ============================================================
   4. SpDatTrangThaiNguoiDung
   Chỉ QUẢN TRỊ HỆ THỐNG

   Bổ sung:
   - không tự khóa
   - không khóa QT hệ thống cuối cùng
   ============================================================ */
CREATE OR ALTER PROCEDURE dbo.SpDatTrangThaiNguoiDung
    @MaQuanTri NVARCHAR(20),
    @MaNguoiDung NVARCHAR(20),
    @TrangThai NVARCHAR(30)
AS
BEGIN
    SET NOCOUNT ON;
    SET XACT_ABORT ON;

    DECLARE @TranBanDau INT = @@TRANCOUNT;

    BEGIN TRY

        IF @TranBanDau = 0
            BEGIN TRANSACTION;
        ELSE
            SAVE TRANSACTION CrudSave;


        IF @MaQuanTri IS NULL
           OR LEN(LTRIM(RTRIM(@MaQuanTri))) = 0
            THROW 51200, N'@MaQuanTri không được rỗng.', 1;


        IF @MaNguoiDung IS NULL
           OR LEN(LTRIM(RTRIM(@MaNguoiDung))) = 0
            THROW 51200, N'@MaNguoiDung không được rỗng.', 1;


        IF @TrangThai IS NULL
           OR LEN(LTRIM(RTRIM(@TrangThai))) = 0
            THROW 51200, N'@TrangThai không được rỗng.', 1;


        /* Chỉ QT hệ thống */
        EXEC dbo.SpKiemTraQuanTriHeThong
             @MaQuanTri = @MaQuanTri;


        IF @TrangThai NOT IN
        (
            N'Đang hoạt động',
            N'Tạm khóa'
        )
        BEGIN
            THROW 51203,
                  N'Trạng thái tài khoản không hợp lệ.',
                  1;
        END;


        /* Kiểm tra tài khoản đích */
        IF NOT EXISTS
        (
            SELECT 1
            FROM dbo.NguoiDung
            WHERE MaNguoiDung = @MaNguoiDung
        )
        BEGIN
            THROW 51202,
                  N'Không tìm thấy tài khoản.',
                  1;
        END;


        /* Không tự khóa chính mình */
        IF @MaQuanTri = @MaNguoiDung
           AND @TrangThai = N'Tạm khóa'
        BEGIN
            THROW 51204,
                  N'Không thể tự khóa tài khoản Quản trị hệ thống đang sử dụng.',
                  1;
        END;


        /* Không khóa QT hệ thống hoạt động cuối cùng */
        IF @TrangThai = N'Tạm khóa'
           AND EXISTS
           (
               SELECT 1
               FROM dbo.NguoiDung
               WHERE MaNguoiDung = @MaNguoiDung
                 AND VaiTro = N'Quản trị hệ thống'
                 AND TrangThai = N'Đang hoạt động'
           )
           AND
           (
               SELECT COUNT(*)
               FROM dbo.NguoiDung
               WHERE VaiTro = N'Quản trị hệ thống'
                 AND TrangThai = N'Đang hoạt động'
           ) <= 1
        BEGIN
            THROW 51205,
                  N'Hệ thống phải còn ít nhất một Quản trị hệ thống đang hoạt động.',
                  1;
        END;


        UPDATE dbo.NguoiDung
        SET TrangThai = @TrangThai
        WHERE MaNguoiDung = @MaNguoiDung;


        IF @TranBanDau = 0
            COMMIT TRANSACTION;

    END TRY
    BEGIN CATCH

        IF @TranBanDau = 0
           AND XACT_STATE() <> 0
            ROLLBACK TRANSACTION;

        ELSE IF @TranBanDau > 0
             AND XACT_STATE() = 1
            ROLLBACK TRANSACTION CrudSave;

        THROW;

    END CATCH;
END;
GO

USE QuanLyThucDon;
