CREATE OR ALTER PROCEDURE dbo.SpThemHoacCapNhatDanhGiaMonAn
    @MaDanhGia NVARCHAR(20),
    @MaNguoiDung NVARCHAR(20),
    @MaMonAn NVARCHAR(20),
    @SoSao INT,
    @NoiDung NVARCHAR(1000) = NULL
AS
BEGIN
    SET NOCOUNT ON;
    SET XACT_ABORT ON;

    DECLARE @TranBanDau INT = @@TRANCOUNT;

    BEGIN TRY

        IF @TranBanDau = 0
            BEGIN TRANSACTION;
        ELSE
            SAVE TRANSACTION ProcSave;

        /* =========================
           KIỂM TRA DỮ LIỆU
           ========================= */

        IF @MaDanhGia IS NULL
           OR LEN(LTRIM(RTRIM(
                REPLACE(REPLACE(REPLACE(
                    @MaDanhGia,
                    NCHAR(9), N' '
                ), NCHAR(10), N' '), NCHAR(13), N' ')
           ))) = 0
            THROW 51031, N'@MaDanhGia không được để trống.', 1;


        IF @MaNguoiDung IS NULL
           OR LEN(LTRIM(RTRIM(
                REPLACE(REPLACE(REPLACE(
                    @MaNguoiDung,
                    NCHAR(9), N' '
                ), NCHAR(10), N' '), NCHAR(13), N' ')
           ))) = 0
            THROW 51031, N'@MaNguoiDung không được để trống.', 1;


        IF @MaMonAn IS NULL
           OR LEN(LTRIM(RTRIM(
                REPLACE(REPLACE(REPLACE(
                    @MaMonAn,
                    NCHAR(9), N' '
                ), NCHAR(10), N' '), NCHAR(13), N' ')
           ))) = 0
            THROW 51031, N'@MaMonAn không được để trống.', 1;


        /* Không cho dùng MaDanhGia của bản ghi khác */
        IF EXISTS
        (
            SELECT 1
            FROM dbo.DanhGiaMonAn WITH (UPDLOCK, HOLDLOCK)
            WHERE MaDanhGia = @MaDanhGia
              AND
              (
                    MaNguoiDung <> @MaNguoiDung
                 OR MaMonAn <> @MaMonAn
              )
        )
            THROW 51030,
                  N'Mã bản ghi đã thuộc đối tượng khác.',
                  1;


        /* Người dùng phải đang hoạt động */
        EXEC dbo.SpKiemTraNguoiDungHoatDong
            @MaNguoiDung = @MaNguoiDung;


        IF @SoSao IS NULL
           OR @SoSao NOT BETWEEN 1 AND 5
            THROW 50008,
                  N'Điểm đánh giá phải từ 1 đến 5.',
                  1;


        IF NOT EXISTS
        (
            SELECT 1
            FROM dbo.NguoiDung
            WHERE MaNguoiDung = @MaNguoiDung
        )
            THROW 50001,
                  N'Người dùng không tồn tại.',
                  1;


        IF NOT EXISTS
        (
            SELECT 1
            FROM dbo.MonAn
            WHERE MaMonAn = @MaMonAn
        )
            THROW 50006,
                  N'Món ăn không tồn tại.',
                  1;


        /* =========================
           THÊM / CẬP NHẬT ĐÁNH GIÁ
           ========================= */

        IF EXISTS
        (
            SELECT 1
            FROM dbo.DanhGiaMonAn WITH (UPDLOCK, HOLDLOCK)
            WHERE MaNguoiDung = @MaNguoiDung
              AND MaMonAn = @MaMonAn
        )
        BEGIN

            UPDATE dbo.DanhGiaMonAn
            SET
                SoSao = @SoSao,
                NoiDung = @NoiDung,
                NgayDanhGia = CAST(GETDATE() AS DATE),

                /* Người dùng sửa -> phải kiểm duyệt lại */
                TrangThaiKiemDuyet = N'Chờ duyệt',
                MaNguoiKiemDuyet = NULL,
                NgayKiemDuyet = NULL,
                GhiChuKiemDuyet = NULL

            WHERE MaNguoiDung = @MaNguoiDung
              AND MaMonAn = @MaMonAn;

        END
        ELSE
        BEGIN

            INSERT INTO dbo.DanhGiaMonAn
            (
                MaDanhGia,
                MaNguoiDung,
                MaMonAn,
                SoSao,
                NoiDung,
                NgayDanhGia,
                TrangThaiKiemDuyet,
                MaNguoiKiemDuyet,
                NgayKiemDuyet,
                GhiChuKiemDuyet
            )
            VALUES
            (
                @MaDanhGia,
                @MaNguoiDung,
                @MaMonAn,
                @SoSao,
                @NoiDung,
                CAST(GETDATE() AS DATE),
                N'Chờ duyệt',
                NULL,
                NULL,
                NULL
            );

        END;


        IF @TranBanDau = 0
            COMMIT TRANSACTION;

    END TRY

    BEGIN CATCH

        IF @TranBanDau = 0
           AND XACT_STATE() <> 0
            ROLLBACK TRANSACTION;

        ELSE IF @TranBanDau > 0
             AND XACT_STATE() = 1
            ROLLBACK TRANSACTION ProcSave;

        THROW;

    END CATCH;
END;
GO

CREATE OR ALTER PROCEDURE dbo.SpKiemDuyetDanhGiaMonAn
    @MaQuanTri NVARCHAR(20),
    @MaDanhGia NVARCHAR(20),
    @TrangThaiMoi NVARCHAR(20),
    @GhiChu NVARCHAR(500) = NULL
AS
BEGIN
    SET NOCOUNT ON;
    SET XACT_ABORT ON;

    /* Chỉ Quản trị nội dung */
    EXEC dbo.SpKiemTraQuanTriNoiDung
        @MaQuanTri = @MaQuanTri;


    IF @MaDanhGia IS NULL
       OR LEN(LTRIM(RTRIM(@MaDanhGia))) = 0
    BEGIN
        THROW 51311,
              N'@MaDanhGia không được để trống.',
              1;
    END;


    IF @TrangThaiMoi NOT IN
    (
        N'Đã duyệt',
        N'Từ chối'
    )
    BEGIN
        THROW 51312,
              N'Quản trị nội dung chỉ có thể duyệt hoặc từ chối đánh giá.',
              1;
    END;


    UPDATE dbo.DanhGiaMonAn
    SET
        TrangThaiKiemDuyet = @TrangThaiMoi,
        MaNguoiKiemDuyet = @MaQuanTri,
        NgayKiemDuyet = SYSDATETIME(),
        GhiChuKiemDuyet =
            NULLIF(LTRIM(RTRIM(@GhiChu)), N'')

    WHERE MaDanhGia = @MaDanhGia;


    IF @@ROWCOUNT = 0
    BEGIN
        THROW 51313,
              N'Không tìm thấy đánh giá.',
              1;
    END;
END;
GO

CREATE OR ALTER PROCEDURE dbo.SpQuanTriXoaDanhGiaMonAn
    @MaQuanTri NVARCHAR(20),
    @MaDanhGia NVARCHAR(20)
AS
BEGIN
    SET NOCOUNT ON;
    SET XACT_ABORT ON;

    /* Chỉ Quản trị nội dung */
    EXEC dbo.SpKiemTraQuanTriNoiDung
        @MaQuanTri = @MaQuanTri;


    IF @MaDanhGia IS NULL
       OR LEN(LTRIM(RTRIM(@MaDanhGia))) = 0
    BEGIN
        THROW 51314,
              N'@MaDanhGia không được để trống.',
              1;
    END;


    DELETE FROM dbo.DanhGiaMonAn
    WHERE MaDanhGia = @MaDanhGia;


    IF @@ROWCOUNT = 0
    BEGIN
        THROW 51313,
              N'Không tìm thấy đánh giá.',
              1;
    END;
END;
GO
USE QuanLyThucDon;
GO

CREATE OR ALTER PROCEDURE dbo.SpQuanTriLayDanhGiaMonAn
    @MaQuanTri NVARCHAR(20),
    @TrangThaiKiemDuyet NVARCHAR(20) = NULL,
    @MaMonAn NVARCHAR(20) = NULL
AS
BEGIN
    SET NOCOUNT ON;

    /* Chỉ Quản trị nội dung được sử dụng */
    EXEC dbo.SpKiemTraQuanTriNoiDung
        @MaQuanTri = @MaQuanTri;

    /* Kiểm tra trạng thái nếu có truyền vào */
    IF @TrangThaiKiemDuyet IS NOT NULL
       AND @TrangThaiKiemDuyet NOT IN
       (
           N'Chờ duyệt',
           N'Đã duyệt',
           N'Từ chối'
       )
    BEGIN
        THROW 51310,
              N'Trạng thái kiểm duyệt không hợp lệ.',
              1;
    END;

    SELECT
        dg.MaDanhGia,
        dg.MaNguoiDung,
        nd.HoTen AS HoTenNguoiDanhGia,

        dg.MaMonAn,
        ma.TenMonAn,

        dg.SoSao,
        dg.NoiDung,
        dg.NgayDanhGia,

        dg.TrangThaiKiemDuyet,

        dg.MaNguoiKiemDuyet,
        qtn.HoTen AS HoTenNguoiKiemDuyet,

        dg.NgayKiemDuyet,
        dg.GhiChuKiemDuyet

    FROM dbo.DanhGiaMonAn AS dg

    INNER JOIN dbo.NguoiDung AS nd
        ON nd.MaNguoiDung = dg.MaNguoiDung

    INNER JOIN dbo.MonAn AS ma
        ON ma.MaMonAn = dg.MaMonAn

    LEFT JOIN dbo.NguoiDung AS qtn
        ON qtn.MaNguoiDung = dg.MaNguoiKiemDuyet

    WHERE
        (
            @TrangThaiKiemDuyet IS NULL
            OR dg.TrangThaiKiemDuyet = @TrangThaiKiemDuyet
        )
        AND
        (
            @MaMonAn IS NULL
            OR dg.MaMonAn = @MaMonAn
        )

    ORDER BY
        CASE
            WHEN dg.TrangThaiKiemDuyet = N'Chờ duyệt' THEN 0
            WHEN dg.TrangThaiKiemDuyet = N'Đã duyệt' THEN 1
            ELSE 2
        END,
        dg.NgayDanhGia DESC,
        dg.MaDanhGia DESC;
END;
GO


USE QuanLyThucDon;
GO

/* ============================================================
   QUẢN TRỊ NỘI DUNG - DUYỆT / TỪ CHỐI ĐÁNH GIÁ
   ============================================================ */

CREATE OR ALTER PROCEDURE dbo.SpKiemDuyetDanhGiaMonAn
    @MaQuanTri NVARCHAR(20),
    @MaDanhGia NVARCHAR(20),
    @TrangThaiMoi NVARCHAR(20),
    @GhiChu NVARCHAR(500) = NULL
AS
BEGIN
    SET NOCOUNT ON;
    SET XACT_ABORT ON;

    DECLARE @TranBanDau INT = @@TRANCOUNT;

    BEGIN TRY

        IF @TranBanDau = 0
            BEGIN TRANSACTION;
        ELSE
            SAVE TRANSACTION KiemDuyetSave;

        /* Chỉ Quản trị nội dung */
        EXEC dbo.SpKiemTraQuanTriNoiDung
            @MaQuanTri = @MaQuanTri;

        IF @MaDanhGia IS NULL
           OR LEN(LTRIM(RTRIM(@MaDanhGia))) = 0
        BEGIN
            THROW 51311,
                  N'@MaDanhGia không được để trống.',
                  1;
        END;

        /* Quản trị chỉ được Duyệt hoặc Từ chối */
        IF @TrangThaiMoi IS NULL
           OR @TrangThaiMoi NOT IN
           (
               N'Đã duyệt',
               N'Từ chối'
           )
        BEGIN
            THROW 51312,
                  N'Trạng thái phải là Đã duyệt hoặc Từ chối.',
                  1;
        END;

        IF NOT EXISTS
        (
            SELECT 1
            FROM dbo.DanhGiaMonAn WITH (UPDLOCK, HOLDLOCK)
            WHERE MaDanhGia = @MaDanhGia
        )
        BEGIN
            THROW 51313,
                  N'Không tìm thấy đánh giá.',
                  1;
        END;

        UPDATE dbo.DanhGiaMonAn
        SET
            TrangThaiKiemDuyet = @TrangThaiMoi,
            MaNguoiKiemDuyet = @MaQuanTri,
            NgayKiemDuyet = SYSDATETIME(),
            GhiChuKiemDuyet =
                NULLIF(LTRIM(RTRIM(@GhiChu)), N'')
        WHERE MaDanhGia = @MaDanhGia;

        IF @TranBanDau = 0
            COMMIT TRANSACTION;

    END TRY
    BEGIN CATCH

        IF @TranBanDau = 0
           AND XACT_STATE() <> 0
            ROLLBACK TRANSACTION;

        ELSE IF @TranBanDau > 0
             AND XACT_STATE() = 1
            ROLLBACK TRANSACTION KiemDuyetSave;

        THROW;

    END CATCH;
END;
GO

/* ============================================================
   QUẢN TRỊ NỘI DUNG - XÓA ĐÁNH GIÁ KHÔNG PHÙ HỢP
   ============================================================ */

