            COMMIT TRANSACTION;

    END TRY
    BEGIN CATCH

        IF @TranBanDau = 0
           AND XACT_STATE() <> 0
            ROLLBACK TRANSACTION;

        ELSE IF @TranBanDau > 0
             AND XACT_STATE() = 1
            ROLLBACK TRANSACTION XoaDanhGiaSave;

        THROW;

    END CATCH;
END;
