UPDATE q
SET SoHienTai = seed.MaxMa
FROM dbo.QuyUocMaHeThong AS q
CROSS APPLY (
    SELECT MAX(TRY_CONVERT(BIGINT, SUBSTRING(MaNguoiDung, 3, 18))) AS MaxMa
    FROM dbo.NguoiDung
    WHERE MaNguoiDung LIKE N'ND[0-9]%'
) AS seed
