BEGIN
    INSERT dbo.[DoanPhimHuongDan] ([MaDoanPhim], [MaCongThuc], [TieuDe], [DuongDan], [MoTa], [ThoiLuong], [TrangThaiSuDung], [NgayCapNhat])
